/* Retained release notes. Data only; presentation stays in foundation.js. */
var RELEASE_HISTORY=[
  ["57.1","24 October 2026","Theatre positions stay visible",["Keeps the four-nurse theatre-position editor open even after an arrangement has been saved.","Adds a direct Edit theatre positions action beside the Pager plan on Night.","Opens the theatre editor first when a theatre vacancy remains, before the shared Pager turns."],"normal"],
  ["57.0","24 October 2026","One clear night plan",["Corrects headcounts after four-nurse theatre changes and keeps Pager setup visible while decisions remain.","Shows readable agreed Pager turns, personal/current/next coverage and equal elapsed DST timing.","Separates provisional four-person arrangements from standard finalisation and retains drafts after save errors.","Compacts headers and Changes, restores scroll-aware navigation and removes duplicate attention badges.","Adds selected-night plan preview/copy/email, roster filter shortcuts and workload sorting.","Strengthens Pager refresh and sign-out cleanup, chat read races and duplicate notification dispatch; updates the guide."],"normal"],
  ["56.8","24 October 2026","Clear four-nurse allocation flow",["Removes the no-allocation-needed panel while the four-nurse theatre arrangement is incomplete.","Keeps the theatre-position editor as the single active task until all four positions are saved.","Leaves Review changes blocked until that arrangement is complete, without contradictory messaging.","Keeps staffing, shared Pager, DST, audit and synchronisation logic unchanged."],"normal"],
  ["56.7","24 October 2026","Cleaner four-nurse changes screen",["Keeps the bottom navigation fixed in one place on mobile with no scroll-driven translation.","Reflows the four-nurse theatre arrangement into a clean single-column mobile layout.","Turns the present-nurse list into compact readable chips and gives every theatre selector full width.","Reduces cramped side-by-side copy and improves spacing through the exceptional allocation flow."],"normal"],
  ["56.6","24 October 2026","Keep iPhone navigation anchored while scrolling",["Keeps the bottom navigation anchored to the bottom edge in the installed iPhone app while scrolling.","Removes the scroll transform used to hide the dock on iPhone, preventing the navigation from jumping into the middle of the roster.","Preserves the compact dock size, iPhone safe-area spacing and keyboard hiding behaviour.","Other platforms keep the existing hide-on-scroll behaviour."],"normal"],
  ["56.5","24 October 2026","Four-nurse night allocation",["When a five-person night drops to four because one nurse is absent, the app shows the four nurses actually present and keeps the remaining theatre positions as rostered.","If a theatre position is vacant, the team explicitly chooses which of the four working nurses fills it; nobody is placed there automatically.","Once two nurses are confirmed in First Part and two in Second Part, the same four nurses manually agree the Pager order for 00:00–07:00.","If the normal Pager nurse is the absent nurse, the original four theatre nurses stay in place and only the Pager order needs to be agreed.","Pager is split equally by real elapsed time: 1h 45m each on ordinary nights and 2h each on the October clock-change night, with current and next cover shown live."],"normal"],
  ["56.4","24 October 2026","Maintenance update",["Internal maintenance only. No clinical allocation, Pager timing or roster behaviour changed."],"normal"],
  ["56.3","24 October 2026","Manual four-person Pager order",["A new four-person Shared Pager order now starts with four explicit Select nurse fields rather than prefilled names.","The app no longer assumes that Pager order should follow First Part or Second Part theatre order.","Each working nurse can be selected only once, and Save remains unavailable until all four Pager parts are assigned.","Existing saved Pager orders remain visible and editable, so previously agreed plans are not lost.","The theatre reassignment and shared Pager timing introduced in 56.2 remain unchanged."],"important"],
  ["56.2","24 October 2026","Move the Pager nurse into a vacant theatre position",["When one nurse is absent from the five-person establishment, Allocation now opens a four-nurse night-only role arrangement instead of leaving the theatre position unresolved.","The usual full-night Pager nurse is suggested automatically in the vacant theatre position, while all four working nurses remain available so the team can confirm the exact theatre arrangement.","The saved reassignment is shared, audited and used by Night, Full roster and the shared Pager display without changing the permanent rotation.","After theatre positions are confirmed, the four working nurses still choose their shared Pager order separately.","Clock-change timing remains based on real elapsed time, so tonight continues to use four two-hour Pager segments."],"important"],
  ["56.1","24 October 2026","Four-nurse shared Pager and clock-change support",["Adds a manual four-nurse shared Pager order when the roster drops to four nurses while maintaining two nurses in each theatre part.","Splits Pager by real elapsed time, giving 1h 45m each on ordinary nights and 2h each on the October clock-change night.","Shows current and next Pager cover, elapsed and remaining time, and each nurse’s own Pager part in the Night hero.","Synchronises the shared Pager order across devices and surfaces it in Changes, Breaks, Full roster, Copy and Email.","Distinguishes the repeated autumn 02:00 hour and keeps normal five, six and seven nurse behaviour unchanged."],"important"],
  ["56.0","21 October 2026","Navigation that makes room for the roster",["Gives the five navigation controls more breathing room without leaving a floating gap below the bar.","Hides phone navigation while scrolling down, then brings it back on upward scroll or at the page end.","Keeps navigation available in Chat, for keyboard focus and when opening another screen.","Updates the tutorial with the new scrolling behaviour while preserving iPhone safe areas."],"normal"],
  ["55.3","21 October 2026","A more compact bottom bar",["Reduces the bottom bar from 68px to 56px while preserving 50px touch targets.","Keeps all five controls aligned and clear of the iPhone home indicator.","Adjusts page and chat spacing to match the smaller bar."],"normal"],
  ["55.2","21 October 2026","Clearer text and roomier phone layouts",["Uses 16px body text and 14px supporting text in the shared interface type scale.","Gives hero duty and break details wider columns, with a separate full-width colleague or coverage row.","Makes roster names and allocation labels easier to read on narrow phones.","Keeps forms readable without focus zoom and replaces the clipped hero clock explanation with a concise timing summary."],"normal"],
  ["55.1", "21 October 2026", "Keep the night hero live after midnight", ["Keeps the hero’s First Part, handover and Second Part visual state aligned with the selected working night after midnight.", "Preserves the clock-change handover, OLD/NEW clock cues and equal elapsed duty timing.", "Shows eight actual hours for full-night Labour Ward/Pager cover, with four hours for each split duty on the autumn clock-change night.", "Separates the repeated-hour timeline labels on narrow phones and removes overlapping duplicate captions."], "normal"],
  ["55.0","20 October 2026","Clearer roster planning and protected saves",["Adds month navigation, a current-month shortcut and an all-published-months view to Full roster.","Shows staffing shortages, unresolved allocations and effective staff workload with Saturday/Sunday counts.","Finds professional names and absence records with accent-insensitive roster search.","Closes direct clinical table writes so saves must use the guarded server functions.","Keeps existing rotation, historical allocations, authentication and change history intact."],"normal"],
  ["54.6","20 October 2026","Safer shared roster recovery",["Rejects older or incomplete shared snapshots before they can replace staffing or allocations.","Keeps the last loaded roster visible and read-only when a refresh fails.","Prevents late roster responses from restoring private data after sign-out or access changes.","Verifies timed-out saves only against a successful online refresh and preserves safe retry identifiers.","Shows the affected night's changes after a save conflict and explains when the latest roster could not be loaded."],"normal"],
  ["54.5","11 October 2026","Quieter roster notifications",["Stops passive attention refreshes from sending device notifications for unresolved allocations or staffing warnings.","Keeps pending decisions, critical warnings and unread chat visible in the app and its badge.","Preserves notifications for saved roster changes and new chat messages."],"normal"],
  ["54.4","11 October 2026","Readable Night allocation messages",["Separates the allocation label, nurse-selection instruction and Review allocation action into distinct left-aligned lines.","Keeps warning icons and chevrons in their own columns, with long role names wrapping cleanly on small phones.","Applies the same layout to Labour Ward decision prompts in light and dark appearance."],"normal"],
  ["54.3","11 October 2026","Reliable staffing activity and clearer allocation review",["Refreshes selected-night activity after shared roster reloads, including saved overtime and absences, without depending on delivery of individual realtime history events.","Rejects outdated history responses when a newer staffing refresh arrives during loading.","Shows loading, offline and retry states instead of claiming there is no activity when history has not loaded.","Uses a readable neutral disabled Review changes button, with white text on the active blue action in both light and dark appearance."],"normal"],
  ["54.2","9 October 2026","Clearer permanent team changes and safer previews",["Permanent team suggestions use the applicable establishment, and changing the effective date preserves entered names and reason.","The preview explicitly shows joining members, leaving members and Pager order; validation and save errors appear beside the form.","The separate seventh-nurse cycle keeps its existing order across period changes, with replacements inheriting the departing member’s place.","Saving prevents double submissions and disables editing until complete; changed or expired previews require a fresh review.","All earlier nights, existing periods and the verified 12 October Pager sequence remain preserved."],"normal"],
  ["54.1","9 October 2026","Preserve Pager continuity at the five-person transition",["Corrected the future starting positions so Pager follows André, Michael Galea, James, Shaun, Michael Debono, then André again, advancing on each four-day roster night.","The original six-person period, all nights through 8 October, clinical records and historical records remain unchanged.","Future five- and six-person period management, staffing, Labour Ward, breaks and account access retain their existing behavior."],"normal"],
  ["54.0","9 October 2026","Five-person establishment and future roster periods",["From 12 October 2026 the permanent roster has two First Part nurses, two Second Part nurses and one full-night Pager, starting with André Bartolo.","Pager advances once on each four-day roster night; all nights through 8 October remain unchanged.","Yentl leaves future permanent rostering while historical records and account access remain separate.","Administrators can preview and schedule future five- or six-person periods, joins, leaves and starting positions in Roster Management.","Absences, overtime, Labour Ward sharing and breaks follow the effective establishment, while five remains the minimum safe staffing threshold.","The tutorial explains normal five-person nights and future roster periods; older clients must update before editing the shared roster."],"normal"],
  ["53.0","9 October 2026","Clear sign-in and safer account management",["Accounts have explicit member or administrator access for each approved sign-in email.","Account changes are verified on the server with saving, error and stale-change feedback.","Adding an existing email no longer resets its role or reactivates it.","The account search is unobstructed and account actions open from Manage.","Google asks which account to use, and deactivated accounts receive a clear explanation."],"normal"],
  ["52.8","9 October 2026","Clearer Account menu and iPhone header spacing",["Account uses clearer labels and line icons.","Generic profile text and database detail are removed from Account home.","Installed iOS headers reserve extra space below the status bar."],"normal"],
  ["52.7","8 October 2026","Solid iPhone status bar backing",["Installed iOS apps use a solid status-bar backing to avoid system edge blur.","The backing follows appearance and never intercepts taps.","Browser checks cover safe-area bounds and scrolling."],"normal"],
  ["52.6","8 October 2026","Clear the Night masthead material",["Removed legacy backdrop filters from the in-flow Night masthead and account button.","Kept floating scroll chrome separate from the clear page header.","Added computed-style checks for the masthead material in the iPhone browser regression."],"normal"],
  ["52.5","8 October 2026","Remove inactive glass from the page header",["Unmounts the inactive blur surface instead of keeping it transparent over the masthead.","Hides the entire scroll header at the top of the page and when a conversation owns its header.","Restores the compact glass title only after the page heading scrolls away."],"normal"],
  ["52.4","8 October 2026","A compact team section beneath your night",["Combines staffing count and plan status beneath Tonight’s team, without the repeated arrangement chip.","Moves Night brief and allocation explanations behind the information button.","Keeps Team allocation and recorded Changes tonight expandable, with full roster and history details still available.","Updates the Night guide for the simplified team section."],"normal"],
  ["52.3","8 October 2026","A clearer Night screen and stable iPhone header",["Keeps the compact header below the iPhone safe area without upward motion or stacked blur.","Collapses Night brief until opened and removes repeated staffing text.","Shows Changes tonight only when changes exist, with full detail available by tapping an entry.","Updates the Night guide for the simpler layout."],"normal"],
  ["52.2","8 October 2026","Keep iPhone chat controls reachable",["Bounds mobile conversations to the visible viewport and respects iPhone safe areas.","Keeps Back, conversation title and composer outside the scrolling transcript.","Adapts conversation height and position when the on-screen keyboard moves the viewport."],"normal"],
  ["52.1","8 October 2026","Keep full-night cover visible",["Shows the full-night Labour Ward / Pager nurse when absences and overtime produce a complete five-nurse plan.","Keeps staffing allocations and break rules unchanged."],"normal"],
  ["52.0","8 October 2026","One Night Roster experience",["Unifies screen spacing, surfaces, typography and Light/Dark status colours.","Connects the dock selection and Actions sheet with restrained motion.","Keeps the live night rail and compact break periods tied to the shared clock.","Shows brief change feedback and return updates that clear when acknowledged.","Improves Chat arrival, loading and scroll behaviour, with colleague shortcuts.","Adds a live Personalise preview and installed-app pull to refresh."],"normal"],
  ["51.4","7 October 2026","Read receipts and startup",["Saves read receipts using the signed-in-user default.","Clears viewed chat and app badges.","Keeps the dock centred while opening."],"normal"],
  ["51.3","7 October 2026","Clear read chat notifications",["Marks visible team and private messages as read even when no scrolling is needed.","Prevents an older background refresh from restoring a cleared unread count.","Clears the installed app badge when no unread messages or attention items remain."],"normal"],
  ["51.2","7 October 2026","Keep Chat visible after signing in",["Restores Chat at the far right of the five-control bottom bar after signing in.","Preserves the same five controls when opening a saved offline roster.","Verifies the sign-in setup for members and administrators, plus normal and fallback navigation."],"normal"],
  ["51.1","7 October 2026","Restore navigation, Actions and the welcome",["Keeps Night, Changes, Actions, Breaks and Chat visible in both the normal and fallback dock.","Restores the Actions sheet layout, readable labels and correctly sized icons.","Separates onboarding progress from Skip and keeps Continue reachable on small phones.","Plays the personal greeting when Night becomes visible, without restarting during background refreshes."],"normal"],
  ["51.0","7 October 2026","One coherent Night Roster",["Uses one compact selected-night context and persistent five-control dock across operational screens.","Replaces duplicate staffing steps with one workflow and puts your break and conversations first.","Opens Personalise, Preferences, Notifications, Security and App & Help as separate Account pages with Back.","Flattens the dark allocation card and separates timeline labels, including clock-change nights."],"normal"],
  ["50.9","7 October 2026","Make personalised greetings automatic and safe",["Uses a valid name entered in Personalise first, then the imported roster name, then the approved account display name.","Rejects sentence-like or malformed personal-name values so phrases cannot appear in the Night greeting.","Applies the same automatic behaviour to existing staff and future users without hard-coding individual names."],"normal"],
  ["50.8","7 October 2026","Consolidate the operational layout",["One visible Changes workflow.","Shared compact shift and staffing context.","Tighter Night and Breaks spacing."],"normal"],
  ["50.6","7 October 2026","Bring the Night hero up to the premium mock-up",["Rebuilds the Night hero presentation around the approved mock-up: larger Mater Dei branding, a compact Main Operating Theatres pill, a stronger integrated shift card, a deeper blue-black atmosphere and a more visible but restrained medical-cross watermark.","Promotes the customizable shift logo, shift name and motto as the hero focal point with larger proportions, clearer internal hierarchy, a subtle divider and controlled blue illumination instead of several equally weighted stacked cards.","Reduces the selected-night control into a quieter glass rail and gives the personalised greeting deliberate breathing room below the team identity so the opening composition feels premium rather than cramped.","Carries the same visual DNA into Changes, Breaks and Chat at lower intensity while keeping Actions, Account, Admin and the bottom dock restrained, task-first and consistent.","Preserves roster calculations, staffing rules, First and Second Part semantics, Malta and DST timing, authentication, database writes, offline safety, clinical state colours, accessibility states and guarded mutation paths."],"normal"],
  ["50.5","7 October 2026","Make shift identity the shared app shell",["Rebuilds the Night opening as one compact branded hero where Mater Dei, Main Operating Theatres, the account control, the customizable shift logo, shift name, motto, selected night and personalised greeting read as one composition instead of stacked competing rows.","Moves Main Operating Theatres into a compact top-row pill, removes the redundant Your night label, enlarges the shared shift identity and gives the greeting deliberate breathing room while keeping the selected-night date control visible and usable.","Carries the same institutional and team identity into Changes, Breaks and Chat at a deliberately lower visual intensity, while keeping each screen's workflow, break plan or conversation as the dominant task surface and giving Actions, Account and administrator utilities the restrained version of the same surface language.","Preserves roster calculations, staffing rules, First and Second Part semantics, Malta and DST timing, authentication, database writes, offline safety, clinical state colours, accessibility states and guarded mutation paths."],"normal"],["50.4","6 October 2026","Complete the unified Night Roster experience",["Restores a clear product-owned selected-night date on Android and iPhone, with explicit visible text styling instead of inheriting the transparent legacy date label state.","Stops an already-running release from repeatedly presenting Finish installing the update when the active PWA controller is already on the same app version, while preserving the deliberate user-approved update flow for genuinely newer releases.","Strengthens the single final product system across Night, Changes, Breaks, Chat, Actions, Account, administrator surfaces and the bottom dock so spacing, typography, surfaces, headers and selected-night context read as one coherent application rather than several generations of UI.","Preserves roster calculations, staffing rules, First and Second Part semantics, Malta and DST timing, authentication, database writes, offline safety, clinical state colours and guarded mutation paths."],"important"],["50.3","6 October 2026","Fix the launch-screen freeze",["Makes the product-owned date label update idempotent so the child-list observer does not create a self-sustaining DOM mutation loop during startup.","Keeps the 50.2 protection that removes late legacy pretty-date wrappers on Night, Changes and Breaks without starving authentication, shared-roster loading or launch recovery.","Adds a deterministic regression contract that rejects unconditional date-label rewrites inside the observed product shell.","Preserves roster calculations, staffing rules, Malta and DST timing, authentication, database writes, offline safety and clinical state colours."],"important"],["50.2","6 October 2026","Remove the legacy mobile date conflict",["Removes the legacy pretty-date wrapper whenever it is injected into the shared roster date control, preventing the old vertical Thursday, day and month layout from coexisting with the new one-line date label.","Keeps one visible date presentation across Night, Changes and Breaks while retaining the native system date picker as the underlying accessible interaction.","Makes the repair resilient to late legacy DOM mutations so installed Android and iPhone PWAs cannot reintroduce the superseded date UI after the modern shell has mounted.","Preserves the 50.1 design language, roster calculations, staffing rules, Malta and DST timing, authentication, database writes and clinical state colours."],"normal"],["50.1","6 October 2026","Unify the app into one professional design language",["Standardises the institution header, logo sizing, account control, page-title hierarchy, spacing rhythm, radii and surfaces across the operational app.","Makes Night, Changes and Breaks share one selected-night component with the same shift identity and date-navigation geometry.","Removes platform-rendered segmented date text from the visible interface and replaces it with a controlled product-owned date label that opens the native picker when tapped.","Keeps Night allocation, Changes workflow, Break plan and Chat conversation as the dominant task on their respective screens while visually demoting secondary information.","Standardises the bottom dock, Actions, Account, live-state presentation, focus treatment and compact-phone behaviour under the same product system.","Preserves roster calculations, staffing rules, First and Second Part semantics, Malta and DST timing, authentication, database writes and clinical state colours."],"normal"],["50.0","6 October 2026","Simplify the Night Roster interface around the nurse",["Compresses the Night opening into a slim institution row, greeting, one compact night selector and the personal allocation without the repeated selected-night and live-status layer.","Makes shift identity a lightweight row inside the selected-night surface instead of another prominent card.","Replaces unreliable native segmented date text with a controlled one-line date label while retaining the native date input as the accessible tap target.","Reduces the personal allocation card height while keeping assignment, live timeline, duty, break and colleague information immediately available.","Applies the same compact selected-night date treatment to Changes and Breaks and reduces top-header volume across Night, Changes, Breaks and Chat.","Reduces bottom-dock height and supporting-card emphasis so the allocation remains the strongest visual element.","Preserves roster calculations, staffing rules, First and Second Part semantics, Malta and DST timing, authentication, database writes and clinical state colours."],"normal"],["49.0","6 October 2026","Consolidate Night Roster into one coherent product system",["Makes product-unified.css the single final product-wide presentation authority and removes the older coherence and bridge files from the active cascade.","Keeps one restrained header, one compact selected-night component and one dominant task surface per screen while preserving the dark personal Night allocation as the visual anchor.","Standardises Actions, Account, Personalisation, live-state indicators, focus treatment and motion so they use the same spacing, radius and surface language as Night, Changes, Breaks and Chat.","Strengthens Android and iPhone compact-phone guards so roster dates remain on one line and the bottom dock, shift identity and break summary keep stable geometry.","Adds regression contracts that reject multiple active coherence stylesheets and protect the shared date, Night, Changes, Breaks, Chat, Actions and Account layout primitives.","Preserves roster calculations, staffing rules, First and Second Part semantics, Malta and DST timing, authentication, database writes, clinical colours and guarded mutation paths."],"normal"],["48.0","6 October 2026","Simplify the whole Night Roster experience",["Retires the 47.0 corrective composition layer that forced unrelated content into oversized combined shells and caused cramped mobile layouts.","Introduces one slim institution header and one clear screen-title rhythm across Night, Changes, Breaks and Chat without turning the entire top of each screen into a single card.","Standardises selected-night context into a compact shared component with shift identity, staffing context and a single-line date control that remains readable on small phones.","Keeps the nurse's personal Night allocation, Changes workflow, personal break summary and team conversation as the dominant surface in their respective screens while secondary information visually recedes.","Rebuilds the bottom navigation as a quieter equal-weight dock with an integrated Actions control rather than a competing floating visual language.","Preserves roster calculations, staffing rules, First and Second Part semantics, Malta and DST timing, authentication, database writes, clinical colours and guarded mutation paths."],"normal"],["47.0","6 October 2026","Unify the whole Night Roster experience",["Turns the Night opening into one true unified shell that contains hospital identity, personalised greeting, shared shift identity and selected-night navigation instead of several visually unrelated layers.","Rebuilds Changes and Breaks into the same compound top-shell grammar, significantly reducing vertical volume while keeping selected-night, staffing and shift identity immediately readable.","Tightens the Changes workflow, personal Night card handoff, Breaks summary, Chat hierarchy and Account grouped surfaces so every destination follows the same spacing, radius and typography rhythm.","Refines the bottom dock into one quieter piece of navigation chrome with a more integrated centre Actions control and consistent selected-state treatment.","Preserves roster calculations, staffing rules, First and Second Part semantics, Malta and DST timing, authentication, database writes, clinical colours and existing guarded mutation paths.","Corrects the release boundary so installed PWAs receive 47.0 through a new versioned app shell and service-worker cache rather than silently retaining 46.2 presentation assets."],"normal"],["46.2","6 October 2026","Compact the Night opening",["Compacts the personalised Night hero and selected-night spacing so the nurse's actual allocation appears higher on phone screens without removing shift identity, date navigation, live status or Focus.","Slows the welcome animation deliberately, including a short pause before the nurse's name and a slower name reveal, while still playing only once per session and respecting reduced-motion settings.","Removes the duplicate visible Your night heading while retaining its accessible section label, reducing repeated hierarchy without changing roster content.","Tightens the handoff from selected-night context through freshness and Focus into the personal allocation, while preserving the live timeline rail, break information, AI Night Brief and daylight-saving clock-change behaviour.","Adds regression coverage for the slower personalised reveal and compact Night hierarchy."],"normal"],["46.1","6 October 2026","Personalise the Night welcome experience",["Replaces the generic Night heading with a personalised time-aware greeting using the saved preferred name, verified roster identity or professional roster name fallback.","Adds a restrained one-time typing reveal for the greeting while respecting the existing greeting preference and reduced-motion accessibility settings.","Keeps the welcome, shared shift identity and selected-night controls inside the existing unified Night hero so the page reads as one coherent personal dashboard rather than stacked unrelated cards.","Adds a concise orientation line that frames allocation, break and team plan as the page hierarchy before the existing Your night, Night brief and Tonight sections.","Ships and caches the dedicated welcome runtime and styles with regression coverage so installed Android and iPhone PWAs receive the same personalised experience."],"normal"],["46.0","6 October 2026","Move Night Roster AI to the Groq free tier",["Moves server-side Night Roster AI requests from the paid OpenAI API endpoint to Groq's OpenAI-compatible Responses API.","Uses openai/gpt-oss-20b as the default model and low reasoning effort to keep requests within Groq free-tier limits while preserving concise roster-grounded answers.","Keeps GROQ_API_KEY entirely inside the authenticated Supabase Edge Function so no provider credential is exposed to the browser or installed PWA.","Preserves the deterministic roster engine as the authority and automatically falls back to the existing roster summary when Groq is unavailable, unconfigured, rate-limited or offline.","Adds regression checks preventing accidental browser-side Groq calls or a return to a paid OpenAI API dependency."],"normal"],["45.9","6 October 2026","Quiet passive roster freshness alerts",["Removes the three-minute age-only stale warning so an otherwise healthy online roster no longer raises a prominent Roster may be stale card simply because no full refresh happened for a few minutes.","Keeps freshness visible in the compact Night status strip while reserving in-app sync warnings for real stale or error states reported by the shared-data runtime.","Stops technical refresh and sync-health items from generating Night Intelligence push notifications or app-badge attention, while preserving meaningful staffing, allocation and conflict alerts.","Adds regression coverage so passive refresh age cannot silently become an attention warning or noisy push path again."],"normal"],["45.8","6 October 2026","Add roster-grounded AI",["Adds a compact Night brief beneath the personal Night hero that summarises the nurse's allocation, staffing state, meaningful overtime context and unresolved roster decisions without replacing the existing hero.","Adds Ask Night Roster, a roster-grounded assistant for questions about allocation, colleagues, breaks, staffing and recorded changes, with an explicit no-patient-information boundary and no ability to mutate the roster.","Adds concise change summaries above Changes tonight so recent staffing and allocation activity can be understood quickly after returning to the app.","Adds Why this allocation explanations that make clear the deterministic rotation, staffing and approved override logic made the allocation and AI is only explaining the effective result.","Adds an authenticated Supabase Edge Function for OpenAI Responses API calls with minimal structured roster context, store=false, authorised-account checks, output limits and a safe deterministic fallback when AI is offline or not configured.","Ships the AI client and styles in the installed PWA cache, adds iPhone and browser regression coverage, and preserves all existing roster safety, offline and write-path guarantees."],"normal"],["45.7","6 October 2026","Focus the Night experience",["Replaces the large always-on Night Intelligence Command Centre presentation with a compact phase and freshness strip so the personal Night hero remains the primary view.","Removes the duplicate My Night, Attention and routine Review this night surfaces from the healthy-state presentation while keeping the underlying attention, conflict, freshness and troubleshooting engine active.","Surfaces the recommended Night Intelligence action only when an important roster warning or unresolved decision is present, reducing repeated information during a normal night.","Turns Calm Mode into a clearer Focus control and hides the whole-team Tonight section while Focus mode is active, leaving the nurse's own allocation and meaningful warnings visible.","Adds focused browser coverage for the compact iPhone presentation and the simplified Focus-mode hierarchy."],"normal"],["45.6","5 October 2026","Complete Night Intelligence",["Adds a Night Command Centre with My Night, shift phase, sync freshness, privacy-preserving presence, an Attention Inbox and a context-sensitive recommended next action.","Adds supported Undo surfacing, concurrent-edit review, roster conflict warnings, long-press person actions, Search & Commands, adaptive density and Calm Mode without creating a second clinical write path.","Makes roster notifications and app badges more meaningful, preserves deep links to the selected night and keeps offline use explicitly read-only with private reminders that never auto-submit shared changes.","Adds an in-app PWA Health Check, guided troubleshooting and accessibility fallbacks while preserving the existing shared Shift Identity and Personalisation Studio.","Ships the intelligence layer in the reviewed Pages bundle and installed-app cache with deterministic, real-browser, low-end and iPhone regression coverage."],"important"],["45.5","4 October 2026","Make iPhone PWA layout a first-class contract",["Stabilises the floating bottom dock above the iPhone Home indicator without shrinking its internal controls, while respecting left and right safe areas.","Hardens Night, Changes, Breaks, Chat, Account and scrolled chrome around iPhone safe areas and prevents WebKit form-focus zoom from disrupting mobile layouts.","Adds a common-iPhone-size regression matrix and runs focused iPhone WebKit browser smoke tests on every pull request before changes can merge."],"normal"],["45.4","4 October 2026","Fix iPhone top controls and pending allocation layout",["Keeps Night, Changes, Breaks and Chat top controls below the iPhone status bar and Dynamic Island by preserving an additive safe-area inset on narrow screens.","Fixes the pending Labour Ward / Pager allocation prompt so its text uses the full amber card instead of collapsing into a narrow grid column.","Adds phone regression coverage for safe-area reachability and the shared-allocation prompt without changing roster, staffing, break or clock-change logic."],"normal"],["45.3","4 October 2026","Keep Night allocation badges visible",["Fixes Team allocation rows so live status chips such as Next, Now and Complete reserve their own space instead of being cropped beside long professional names.","Lets paired professional names wrap naturally while keeping the You badge, live state and row chevron readable across small phone widths.","Adds browser regression coverage for the long-name Second Part allocation layout without changing roster, break or clock-change logic."],"normal"],["45.2","4 October 2026","Refresh onboarding and tutorial",["Rebuilds first-use onboarding as an eight-step current-app tutorial covering identity, Night, Changes, Actions, Breaks, Team Chat, Account and Personalisation, sharing, installation and reusable help.","Updates the App Guide into a complete Tutorial & app guide with one-tap lessons for Night, Changes, Actions, Breaks, Team Chat, Full roster, Account & Personalise, sharing and update history.","Advances the education generation so existing users receive the refreshed walkthrough once, while updated Changes, Breaks and Chat tips can be rediscovered without repeating them after the full tutorial is completed.","Makes Skip for now genuinely temporary and keeps the complete tutorial replayable from Account, while preserving clock-change guidance, roster logic, staffing rules and shared-data behaviour."],"normal"],["45.1","4 October 2026","Simplify Night actions and activity",["Removes redundant Night actions so personal allocation, team allocation and Breaks each have one obvious route instead of repeated full-width shortcuts.","Collapses unresolved staffing and allocation prompts into one clear amber decision card while preserving separate confirmation actions when they are genuinely required.","Reformats Changes history and Night activity into compact structured rows with clearer hierarchy, metadata and state styling.","Strengthens the Review changes action and pending workflow styling without changing roster calculations, staffing rules or clock-change logic."],"normal"],["45.0","4 October 2026","Polish the complete night experience",["Unifies typography, spacing, surface depth and colour hierarchy across Night, Changes, Breaks, Chat, Full Roster and Personalise.","Makes Changes decision-first by keeping the Staffing → Allocation → Confirm workflow prominent while moving secondary explanations behind calm on-demand disclosure.","Improves Full Roster scanning with role-aware grouping and increases the readability of secondary labels, statuses and supporting information across the app.","Refines the shared shift identity, collapsed scroll chrome, bottom navigation, chat bubbles, break schedule and Personalisation Studio with restrained motion and accessibility fallbacks."],"normal"],["44.5","4 October 2026","Move app utilities into a side drawer",["Persistent gear and install controls have been removed from the visible top bars; the avatar is now the single entry point for account and app utilities.","Account now opens as a right-edge drawer with direct destinations for Personalise, Notifications, Appearance, App & Help, Security and administrator-only Roster management.","Night uses the freed space to reduce top chrome and remove the redundant staffing chip while preserving the shared shift identity as the visual anchor.","Notifications opens the existing Chat alert controls directly, while Roster management continues to use the existing administrator area and permissions."],"normal"],["44.4","4 October 2026","Unify the Night context hero",["Night now treats the Mater Dei utility strip, Night title, shared shift identity and selected date as one unified top hero rather than separate floating sections.","The shared shift artwork and name remain the personality anchor inside the hero, with room for the tagline to wrap naturally.","Previous and next night controls are embedded directly into the full-width date navigator instead of floating separately at the edges of the screen.","Staffing remains available as a small subordinate chip so it never competes with the date, while Your night begins immediately below the unified hero."],"normal"],["44.3","4 October 2026","Let mobile context breathe",["Changes and Breaks no longer squeeze Main Operating Theatres beside the Mater Dei logo; the unit label can use its own line and never ellipsises.","Selected-night staffing moves into a small context chip so the date navigator gets the full card width and can show the complete date and roster-night label.","Shift identity remains prominent with a large artwork tile, full shift name and wrapping tagline rather than sacrificing team personality for density.","Primary context across Night, Changes and Breaks now wraps instead of truncating when screen width or text scaling needs more room."],"normal"],["44.2","4 October 2026","Compact the selected-night header",["Changes and Breaks use a tighter institutional masthead with the information action aligned inside the title row instead of occupying a large empty area.","The shared shift identity is amplified with a larger fixed artwork stage, stronger name hierarchy and clearer tagline while the surrounding context takes less vertical space.","Selected-night date and staffing controls are consolidated into a compact context surface, allowing Manage this night and the break plan to appear higher on phone screens.","Breaks now establishes shift and selected-night context before the personal break card so the screen follows the same where, when, what hierarchy as the rest of the app."],"normal"],["44.1","4 October 2026","Polish shift identity and review readability",["Shared shift names now use neutral high-contrast text, while the chosen shift accent is reserved for the icon, border and subtle surface tint.","Team Chat gives the shared shift icon a fixed identity stage and more breathing room so the icon can never crowd the shift name on phone screens.","Pending seventh-nurse review cards now use dark primary copy with amber only as an emphasis cue, fixing the washed-out yellow text."],"normal"],["44.0","4 October 2026","Introduce Personalisation Studio",["Account now includes a dedicated Me and Our Shift Personalisation Studio with live identity previews instead of scattered cosmetic settings.","Members can personalise their own avatar style, preferred name, professional title, accent, text size, motion and greeting while verified roster identity and clinical colours stay protected.","The whole shift can share one name, optional tagline, symbol, accent and private team picture across Night and Team Chat.","Shift images are restricted to authorised shift members, personal photos remain private to their owner, and generated identity fallbacks keep the app polished without requiring uploads."],"important"],["43.5","4 October 2026","Make shift identity persistent and more distinctive",["The shared shift name now belongs to the team rather than one roster date, so it stays visible when moving between every published night.","Existing shift names are carried forward automatically and the database now treats rename or removal as one global team identity while retaining the guarded shared-write and audit protections.","The Night header gives the shift identity a richer glass badge with a dedicated identity mark, stronger typography, depth and a subtle reveal without competing with the selected date.","Changes, Breaks and Chat continue to use the same shared identity, while the naming sheet now explains clearly that the name applies across every roster night."],"normal"],["43.4","4 October 2026","Give Chat and shift identity a premium visual hierarchy",["Team Chat is promoted into a richer featured conversation surface with a larger team icon, stronger shift title, cleaner metadata and more deliberate depth.","Chat essentials are rebuilt as one premium glass surface with generous safety and notification rows, larger icons, clearer typography and better touch targets.","Zero unread counts are never rendered as badges; unread indicators now appear only when there is something that genuinely needs attention.","Direct messages gain larger avatars, names and previews with improved spacing so the inbox feels more confident and easier to scan on a night shift.","Shared shift names are larger and more distinctive across Night, Changes, Breaks and Chat, using one consistent identity treatment without overpowering clinical information."],"normal"],["43.3","4 October 2026","Rebuild Chat around the night team",["Chat is rebuilt around one compact conversation language: Team Chat and direct messages now share aligned avatars, names, previews, timestamps and unread states without oversized dashboard cards.","The header and selected-night context are tighter and calmer, while safety guidance and notification preferences move into a quiet footer so conversations remain the primary task.","Any roster member can give the selected shift a shared nickname of up to 28 characters; the name is stored per roster night, synchronises across devices and can be renamed or removed.","A shift nickname becomes the Team Chat identity and also appears subtly beside the selected night in Night, Changes and Breaks, while Anaesthetic Team remains visible as the clinical context.","Shared shift-name writes are protected by the existing authenticated compatibility boundary, audited server-side, included in startup and offline snapshots, and propagated through shared revision and realtime updates."],"normal"],["43.2","4 October 2026","Refine Chat into a calmer native inbox",["Team Chat now uses a compact near-background conversation surface with a restrained accent edge, smaller avatar and clearer timestamp hierarchy.","Private conversations now use purpose-built messaging rows so names, previews, timestamps and unread badges stay aligned as one coherent item.","Message previews are shorter and more natural: private rows no longer repeat the colleague name and Team Chat no longer prefixes every preview with Latest.","Safety guidance and notification settings are now grouped into one quiet secondary utility surface rather than competing with conversations.","The active bottom-navigation lens is visually inset and the Actions control is calmer, preserving the same tested navigation geometry while reducing visual bulk."],"quiet"],["43.1","4 October 2026","Make Chat conversation-first",["The large all-in-one Chat card has been replaced by separate Team and Private conversation sections with cleaner spacing and much less visual bulk.","Anaesthetic Team is now one fully tappable conversation row with a clearer title, timestamp, member count and latest-message preview, without a redundant Open chat button.","Private chats now use larger names, more readable previews, quieter timestamps and unread badges, and no redundant chevrons.","The Chat header is tighter and more balanced, with the compose action integrated beside the title instead of appearing as a detached control.","Safety guidance and notification settings remain accessible but are visually demoted so they no longer compete with the messaging task."],"quiet"],["43.0","4 October 2026","Refine mobile hierarchy and readability",["Primary screen titles, section headings and supporting text now use one calmer mobile type scale with more consistent spacing across Night, Changes, Breaks and Chat.","Night keeps the personal assignment as the visual priority while reducing competing emphasis in timeline details, status messaging and the Tonight summary.","Changes now lets completed workflow stages recede and gives unresolved allocation decisions, including the seventh-nurse choice, a clearer and more accessible focus.","Breaks is more compact around pending states and selected-night context so the actual break plan appears sooner without hiding any staffing information.","Chat now uses a compact compose control, denser native-style conversation rows and more disciplined unread/status treatments, while the bottom navigation is easier to read and less visually dominated by Actions."],"quiet"],["42.9","4 October 2026","Keep administrator alerts administrative",["The administrator settings gear no longer repeats selected-night review work such as an unresolved seven-nurse allocation.","Night-specific decisions remain clearly surfaced through Changes and Quick Actions, where they can actually be resolved.","The administrator badge now counts only pending access requests and roster publication attention.","Browser regression coverage verifies that a selected-night task alone leaves the settings gear clear while a pending access request still raises it."],"quiet"],["42.8","3 October 2026","Show every recorded overtime nurse",["Recorded overtime names on Tonight now wrap naturally instead of being truncated on narrow phones.","Multiple overtime nurses remain fully readable while a seven-nurse role decision is unresolved.","The 42.7 staffing visibility and administrator attention badge fixes remain unchanged.","Browser coverage now verifies that long and multiple overtime names do not overflow or disappear."],"quiet"],["42.7","3 October 2026","Keep recorded staffing visible while decisions are pending",["Tonight now names recorded overtime nurses as well as showing the overtime count, including while a seven-nurse decision is still pending.","Seven-nurse decision state remains provisional until the allocation is resolved, but it no longer obscures who has already been recorded as overtime cover.","The administrator settings attention badge is repositioned so the circular header control no longer clips it into a red crescent.","Browser coverage now protects both pending seven-nurse overtime visibility and the administrator badge geometry."],"quiet"],["42.6","3 October 2026","Restore reliable signed-in visibility",["Restores the authoritative hidden-state utility outside the legacy cascade so authenticated screens can reliably hide the sign-in gate and other inactive interface surfaces.","Fixes the 42.5 regression where Google and password authentication succeeded but the sign-in screen could remain visible over the authenticated roster.","Browser smoke setup now uses the production hidden class instead of forcing inline display styles, so this visibility regression is caught in future UI changes.","Architecture coverage now protects the hidden-state contract while preserving the lower-priority legacy CSS ownership introduced in 42.5."],"quiet"],["42.5","3 October 2026","Stabilise the app-wide visual cascade",["Historical base styling is moved into a low-priority legacy layer so old high-specificity rules can no longer unexpectedly override the current interface across Night, Changes, Breaks, Chat, sheets and administration.","Presentation generations before the 42.4 foundation remain available as compatibility styling but are demoted to a historical cascade layer and stripped of obsolete priority flags.","Chat keeps its complete fallback styling in a lower-priority feature layer, allowing the current shared presentation system to own overlapping controls consistently.","Repository architecture tests now guard CSS ownership so future polish cannot silently reintroduce the same legacy-versus-current cascade conflicts."],"normal"],["42.4","3 October 2026","Make Night calmer and navigation smoother",["Night removes the duplicate Personalise this view settings row and keeps the hero focused on assignment, live timing, break, colleague context and one full-night action, while preserving the OLD/NEW clock-change wake-up cues and equal-duty handover logic.","Primary-screen swipes no longer drag and animate two full application pages behind the finger; gestures now decide the destination and use a short compositor-only settle while each tab keeps its own saved scroll position.","Night, Changes and Breaks now share a 44 px date-control baseline, and the Breaks summary actions use proper touch-target sizing instead of undersized calendar-adjacent controls.","The five-column dock has one authoritative geometry, with a quieter translucent Actions control, matching label and icon rhythm, a transform-only active lens and the existing corrected unread-badge anchoring."],"normal"],["42.3","3 October 2026","Fix dock notification badge clipping",["Chat and Changes unread badges now remain fully visible because the shared icon stage explicitly allows the badge to extend beyond the icon box.","The legacy Chat badge offset is limited to the non-React fallback navigation, preventing it from interfering with the current five-column dock.","Badge margins and positioning are normalised in the consolidated dock layer so active and inactive tabs use the same stable geometry."],"quiet"],["42.2","3 October 2026","Correct Night colour and dock geometry",["The Night hero now uses a self-contained dark colour system with bright assignment text, muted supporting copy, subtle role colour and a dark translucent Duty, Break and Colleague surface instead of mixed light-theme tokens.","Timeline, More details, full-night action and clock-change cues now inherit the same hero palette, preserving OLD/NEW clock clarity while improving contrast and visual hierarchy.","Night date controls and the Tonight card are refined with quieter neutral surfaces and more restrained shadows so blue and green are reserved for interaction and status.","The five bottom destinations now use matching fixed icon stages; Changes and Chat badges are anchored to their icons, Actions uses the same vertical geometry, and the active lens/dock glass are lighter and more Apple-like without obscuring labels."],"normal"],["42.1","3 October 2026","Unify the presentation foundation",["Changes now uses a calmer grouped workflow with tighter date, staffing, step, empty-state and history surfaces while keeping the existing save and validation logic unchanged.","Breaks now presents the personal break, summary, schedule and coverage information as clearer grouped surfaces with less competing chrome.","Chat now uses denser inbox, safety, thread and composer spacing so more conversation fits on screen without changing delivery, retention, unread or notification behaviour.","The Night and five-column dock CSS are consolidated: clipping-prone negative margins and superseded finishing overrides are removed, while the validated 360 to 412 pixel Night layout and OLD/NEW clock-change behaviour remain authoritative."],"normal"],["42.0","3 October 2026","Rebuild the UI foundation",["The Night assignment hero no longer clips longer Duty, Break, colleague or assignment text, with safe internal gutters and responsive layouts validated at 412, 390, 384 and 360 pixel phone widths.","Duty, Break and Colleague now use a two-plus-one arrangement on typical phones and a single-column fallback on very narrow screens, while the live 00:00–07:00 timeline wraps safely without changing clock-change or handover logic.","Changes, Breaks, Chat and Full roster now share the same screen-header and roster-date presentation hooks, giving titles, controls, spacing and typography a consistent hierarchy across the app.","The five-column glass dock receives a quieter active lens and safer unread-badge placement, while the grouped Tonight surface and all existing roster, Supabase, authentication and daylight-saving behaviour remain unchanged."],"normal"],["41.9","3 October 2026","Polish Night composition and spacing",["The Night header and date selector are tightened so the page title, date and assignment sit on one consistent 8-point spacing rhythm.","The redundant assignment eyebrow is removed on normal nights, while the hero keeps the assignment, timeline, Duty, Break, Colleague, More details and one full-night action in a clearer hierarchy.","Tonight is regrouped into one operational surface containing team status, Team allocation and Changes tonight, with Plan ready attached to the team information instead of floating separately.","The bottom dock is reduced to a 64px balanced five-column glass bar with a smaller integrated Actions control, refined unread badge placement and safe content clearance."],"normal"],["41.8","3 October 2026","Make clock-change time unmistakable",["Clock-change nights now show a large live current-time card marked OLD or NEW, with a clear NOW badge and plain-language confirmation of whether the clock change has already happened.","When clocks go back, the repeated 02:xx hour is labelled FIRST 02:xx before the change and SECOND 02:xx after it, so identical wall-clock times cannot be confused.","The compact live timeline label mirrors the same OLD clock and NEW clock wording while the existing equal-duty handover, repeated-hour timeline and staffing logic remain unchanged.","The wake-up cue includes dark-mode, reduced-motion and reduced-transparency treatment and is covered by browser regression tests for both occurrences of 02:15."],"normal"],["41.7","3 October 2026","Rebuild the Night screen",["The Night assignment card is cleaner and more focused, with Duty, Break and Colleague details plus one full-night action instead of repeated handover information.","Normal nights show 03:30 only as the timeline division, while clock-change nights keep their special equal-duty handover, repeated-hour or skipped-hour explanation clearly visible.","Tonight, Team allocation and Changes tonight now use a tighter hierarchy, stronger dark-mode contrast and more consistent spacing so the screen is easier to scan during a shift.","The bottom navigation is rebuilt as a balanced five-column glass dock with an integrated Actions control, better badge placement, safe scroll clearance and reduced-motion and reduced-transparency fallbacks."],"normal"],["41.6","2 October 2026","Polish the app shell",["The bottom Night, Changes, Breaks and Chat rudder has larger destination labels, a better integrated centre Actions control and a lighter glass material that lets moving content remain visible underneath.","Compact scroll headers now show useful screen context where available, use a more legible hierarchy and transition into a genuinely translucent navigation surface instead of an opaque strip.","The Changes workflow control now settles beneath the compact header when sticky, preventing competing chrome while keeping the three-step workflow immediately accessible.","Night and the other primary screens use tighter, more consistent vertical spacing so the first viewport carries more useful information without making cards or controls feel cramped."],"normal"],["41.5","2 October 2026","Make Night easier to read",["The personal Night hero is substantially shorter and now prioritises assignment, live duty state, handover timing, duty period and break, with a slim direct route to team allocation and profile detail moved behind progressive disclosure.","Tonight is calmer and less repetitive: the duplicate break shortcut and secondary quick-status strip are removed while the team plan, allocation and recent changes remain immediately available.","The centre Actions rudder is smaller and better integrated with the navigation, uses clearer labelling and attention counts, and rotates into a close state while its sheet is open.","The Actions sheet now grows from the centre navigation with restrained motion and presents staffing, review, messaging and sharing actions in a faster two-level hierarchy with reduced-motion fallbacks."],"normal"],["41.4","2 October 2026","Make night actions easier to reach",["The bottom navigation now uses an integrated centre Quick button between Changes and Breaks while Night, Changes, Breaks and Chat remain the only page destinations.","Quick Actions opens a night-aware sheet for reporting an absence, adding overtime cover, reviewing outstanding changes, starting a private message and sharing the public Night Roster app.","Staffing shortcuts route into the existing guarded Changes workflow and respect offline or server-side write restrictions instead of creating new mutation paths.","The new rudder and sheet retain large touch targets, reduced-motion and reduced-transparency fallbacks, visible focus states and a restrained Liquid Glass treatment."],"normal"],["41.3","2 October 2026","Make Account and Administrator calmer",["Account now opens to four clear destinations: Profile, Preferences, Security, and App & Help, instead of placing every setting and action in one long sheet.","Administrator now opens to Tonight, People & Access, Roster Management, and System, replacing the crowded five-tab control rail with a task-focused landing view.","Publishing and permanent team rotation are grouped behind Roster Management, while system health, recent admin activity, exports and diagnostics are grouped under System.","Technical health and audit detail stays collapsed until requested, while the existing roster, account, passkey, export and administrator actions continue to use their proven underlying logic."],"normal"],["41.2","2 October 2026","Finish the modular runtime architecture",["The former app-ui.js source is split into foundation, clinical, synchronization and bootstrap modules, while the public app-ui.js remains a generated compatibility asset for installed PWAs.","Domain clock, freshness and capability logic plus the reliability runtime now live in strict TypeScript source and must typecheck before compatible browser JavaScript is generated.","Release tooling and architecture tests now reject stale generated assets or a return to the previous monolithic source layout.","Superseded one-off presentation boundary notes were removed after durable ownership and safety rules were consolidated into AGENTS.md.","The verified 138-night rotation, staffing and Labour Ward rules, Supabase trust boundary, audit schema, Chat transport and explicit ACTIVATE_UPDATE flow are unchanged."],"normal"],["41.1","2 October 2026","Make recovery and audit durable",["Repeated failed launches now enter a reduced-risk recovery mode, saved rosters use bounded integrity-checked atomic IndexedDB snapshots, and the active service worker can verify and repair missing cached shell files without bypassing explicit update approval.","Consequential shared roster writes now create immutable server-side audit events with operation IDs, authenticated actor identity and before/after values, with an administrator timeline for review.","Night history now uses bounded keyset pagination, operation idempotency records expire after 90 days, and new database invariant and non-mutating canary checks strengthen long-running health monitoring.","Critical roster requests now collect bounded privacy-safe latency measurements, with CI size budgets guarding against performance drift.","Release testing now includes WebKit/iPhone coverage, low-end CPU and network pressure, ambiguous retry idempotency, real two-page leadership, active-session revocation and a verified roster-data restore drill."],"normal"],["41.0","2 October 2026","Enforce the roster trust boundary",["Shared roster writes now require a compatible 41.x client, while the server can pause shared editing or block a specific unsafe release without stopping roster viewing.","Older v25, v26, v35 and v48 mutation routes are no longer executable by signed-in browsers; current roster changes use the guarded v49 route.","Audit history now records the authenticated account UUID and resolves the readable actor name on the server instead of trusting a browser-supplied name.","Access and role changes now reach open and multi-tab PWAs; disabled accounts clear private saved roster and Chat state and sign out immediately."],"important"],["40.1","2 October 2026","Make Chat easier to read and use",["Chat messages, timestamps, thread titles and inbox rows now use a more readable night-shift type scale, with clearer unread and active-conversation states.","New private chat keeps a visible text label even on phones, and the Anaesthetic Team entry remains the dominant first action with a clearer Open chat affordance.","Phone conversations use a cleaner full-canvas thread with larger controls, while desktop keeps the inbox and conversation side by side.","The composer is now one polished translucent surface with a plain textarea and 44 px send control, and private outgoing messages use a clearer blue treatment without changing chat delivery logic."],"important"],["40.0","2 October 2026","Make shared roster changes safer",["Every clinical roster change now carries a unique operation ID and the latest shared revision to the database, so double taps, retries and lost responses cannot quietly repeat the same action.","Before consequential changes are saved, the app checks that its shared roster revision is still current; if another device changed the night, the latest plan is loaded and the affected roles or staffing state are shown for review.","Final confirmation now has an additional server-side safety gate that rejects understaffed plans, stale role overrides, unavailable staff and invalid Labour Ward orders before the proven allocation and revision-locked finalisation logic runs.","App startup, resume, online recovery, Night rollover, freshness checks, Realtime recovery and update checks now run through a shared lifecycle and scheduler instead of competing timers and independent browser events.","Multiple tabs on the same device coordinate through a local leader so only one owns roster Realtime and routine update polling, while other tabs follow shared revision broadcasts and can take over automatically if the leader closes.","Clock checks now reject unreliable high-latency samples, device storage is routed through one compatibility facade, stable machine error codes replace wording-dependent decisions, and privacy-safe diagnostics record state, recovery and command events without roster identities.","New adversarial tests add generated staffing combinations, stale-client and retry contracts, lifecycle and clock checks, multi-tab coordination safeguards and continued protection for the verified 138-night rotation and explicit PWA update activation."],"important"],["39.0","2 October 2026","Harden the roster logic foundation",["Night now uses one Malta-time context for automatic versus manual selection, current and next night labels, live duty phase and the 07:00 boundary, with an authenticated server-clock sanity check when online.","Night, Changes and Breaks now share one selected-night plan model, while shared synchronization has explicit starting, live, reconnecting, offline and stale-data states and rejects older snapshots arriving after newer ones.","Shared roster mutations now use one guarded command path that collapses duplicate in-flight actions and verifies the refreshed server outcome after an ambiguous timeout while preserving existing atomic RPCs and revision-conflict protection.","Chat retries now carry a stable client message ID with database-enforced idempotency, and read cursors can only move forward across tabs and devices.","Saved offline roster data now expires after seven days, diagnostics use a bounded privacy-safe local event ring, schema capabilities are centralized, compatibility startup fallbacks are observable, and post-update runtime versions are checked for consistency.","Typed internal event contracts and new invariant tests cover all 138 published rotation nights at the 19:00 and 07:00 boundaries, plus multi-device, retry, stale-snapshot and update-health contracts."],"important"],["38.02","1 October 2026","Make Night follow the working-shift clock",["From 00:00 through 06:59, Night keeps showing the roster night whose shift is still in progress, including its live timeline and handover state.","At 07:00 Malta time, once that duty window ends, Night automatically moves to the following rostered night rather than leaving the completed night selected.","During the daytime and evening before duty begins, the app keeps showing that next rostered night; once its working night is active, it is labelled Current roster night.","The date control now distinguishes Current roster night from Next roster night correctly, avoiding the earlier misleading label on future dates.","The same clock rule is rechecked every minute and whenever the app becomes visible, while manual date browsing remains respected until the automatic-night shortcut is used."],"important"],["38.01","1 October 2026","Restore quiet headers and one glossy scroll bar",["Night, Changes, Breaks and Chat no longer use the large blue-green hero masthead introduced in 38.0; their normal top-of-page headers are quiet and content-led again.","A single slim full-width glass bar now fades and glides in only after the page header scrolls away, using the same treatment across Night, Changes, Breaks, Chat, Full Roster and Roster Management.","The scroll bar shows only the current section title, removing extra status text, oversized height and the Admin-only floating rail so the chrome stays calm and predictable.","Scroll-linked blur, opacity and vertical movement are driven continuously for a smoother transition, while screen switches temporarily suppress the bar to prevent stale-header flashes.","The improved Chat readability, content hierarchy, roster calculations, handover logic, staffing rules, break logic, Supabase security and explicit PWA update activation remain unchanged."],"important"],["38.0","1 October 2026","Unify the app around a premium clinical interface",["Chat is rebuilt around readable team and private-message hierarchy, larger conversation text, cleaner previews, stronger unread states and better use of the available screen instead of tiny labels surrounded by empty space.","Changes and Breaks now use the same premium masthead, typography, spacing, surfaces and interaction language while preserving the existing staffing workflow and calculated break plan.","The compact scrolling header now morphs into a slim full-width glass veil with useful context such as unread messages or outstanding Changes items, replacing the previous detached-looking top bar.","Night, bottom navigation, Account, roster management, dialogs and update surfaces now share the same restrained clinical palette, radii, depth, touch geometry and accessibility fallbacks.","The redesign changes presentation only: the verified rotation, real handover calculation including clock-change nights, staffing rules, break logic, chat delivery, Supabase security and explicit PWA update activation remain unchanged."],"important"],["37.99","1 October 2026","Give Night a quieter focus",["Night now opens with a leaner hospital header, one clear page title and a lighter date navigator, removing repeated labels while keeping the selected roster night obvious.","Your assignment hero is calmer and more compact while preserving the live handover rail, colleague, duty and break information, clock-change guidance and every existing roster calculation.","As Night scrolls, the hospital masthead now morphs into a compact glass header carrying your assignment and selected date instead of leaving an empty collapsed header.","The update prompt and bottom navigation are smaller, clearer and more genuinely translucent, with quieter secondary actions, a refined active state and reduced-transparency fallbacks.","During the active working night, the interface subtly increases emphasis on the assignment and handover instrument without changing staffing, allocation, break or PWA update behaviour."],"important"],["37.98","1 October 2026","Fix Share Night Roster buttons",["Send Night Roster now dispatches through the correct share action channel and opens the device share sheet where supported.","Copy link and Installation help use the same corrected share event path instead of silently doing nothing.","Browser coverage now clicks the real Send Night Roster button and verifies that only the public Night Roster welcome URL is shared."],"important"],["37.97","1 October 2026","Bring back the live blue Night rail",["The Night timeline is now a slim blue elapsed-time rail with a soft highlight for your own duty segment, a live blue progress fill and moving marker during the active night, and a crisp handover marker without the previous chunky segmented panel.","The What matters next / Handover state is now integrated directly into the dark hero instead of appearing as a large pale nested card, while colleague, duty and break facts keep proper high contrast inside the hero.","Clock-change intelligence is preserved on the cleaner rail, including the first and second 02:xx labels on autumn rollback nights, the spring skipped-hour marker, equal-duty handover timing, and reduced-motion support."],"important"],["37.96","1 October 2026","Make Night feel like a live shift",["The personal Night hero now adapts through the shift with a live what-matters-next state, actionable colleague, duty and break details, subtle handover feedback, and compact routine-versus-exception context across the Night overview and team allocation.","The 00:00–07:00 rail is now a true elapsed-time instrument with highlighted personal duty segments, a live moving marker, explicit handover state and clock-change geometry; autumn rollback nights visibly distinguish the first 02:xx from the second 02:xx, while spring nights show the skipped hour.","Share Night Roster now provides a large offline QR code, native phone sharing, copy-link fallback and installation help. Scanned links open a simple device-aware install welcome flow, while sharing exposes only the public app address and never roster or account data."],"important"],["37.95","1 October 2026","Keep clock-change nights fair",["Clock-change nights now keep First Part and Second Part equal in real elapsed duty: the handover moves to 04:00 on spring-forward nights and to 03:00 after the rollback on autumn nights, while ordinary nights remain 03:30.","Night, Breaks, personal live-duty status and full-roster summaries now share the same Europe/Malta timing calculation, with clear actual-hours wording, animated clock-change guidance and reduced-motion support.","Affected nights now receive contextual onboarding, a one-time advance reminder when the roster night is within seven days, and a once-per-night device notification when alerts are already enabled, without introducing a new permission prompt."],"important"],["37.94","1 October 2026","Make the next safe action obvious",["Changes now opens on the step that actually needs attention for each selected night and shows genuine progress toward a ready or shared plan, while the standard automatic six-nurse plan stays quiet.","Notification permission is no longer requested just after sign-in. Night Roster first lets the user reach Team Chat, then offers optional alerts with benefit-first privacy wording and keeps the operating-system permission behind an explicit tap.","Unfinished local Changes selections now warn before a browser reload and block a PWA update from discarding them, while confirmation labels Rostered versus This night so exceptional changes are easier to compare before sharing."],"normal"],["37.93","1 October 2026","Make guidance part of the app",["First use is now a focused three-step setup: confirm your roster identity, learn where your own night appears, and understand that the normal six-nurse plan is automatic unless something genuinely changes.","Changes, Breaks and Team Chat now explain themselves the first time they are opened, while Account has a proper App Guide with reusable topic shortcuts and one education-state system that still respects earlier completed guidance.","What’s New is now benefit-led and easier to scan, with feature actions, a compact expandable month-grouped version history, smarter quiet/normal/important release visibility, and update read-state recorded only after the update experience is actually viewed."],"important"],["37.92","1 October 2026","Make the night feel alive",["Night now shows a live duty-state cue, a non-countdown 00:00–07:00 orientation rail, an at-a-glance strip for current state, personal break and unread Chat, a calmer seven-nurse information treatment, smarter since-last-open activity summaries and Jump to me navigation.","Changes now treats an already published plan as a calm completed state with a compact Shared workflow and a quieter View or adjust roles action, while healthy realtime copy is reduced to Up to date and genuine unresolved work still restores the stronger action state.","Breaks now reads as one grouped schedule with Jump to me and structured Labour Ward, Pager and seventh-nurse coverage rows, while shared typography, semantic colours, reduced card furniture, stronger content-under-glass chrome, subtle haptics and accessibility fallbacks are applied across the core app."]],["37.91","30 September 2026","Make settings easier to read",["Notification settings now use larger row titles and descriptions, bigger switches, and visible On, Off or Muted labels so state never depends on colour alone.","Notification colour is simplified: the app accent marks interactive and enabled controls, green is reserved for healthy device status, warning and destructive colours keep their semantic roles, and mute actions use quieter neutral controls.","Account, appearance and roster-management utility surfaces now share larger settings typography, roomier tap targets and clearer grouped-row hierarchy without changing roster, notification or security behaviour."]],["37.90","30 September 2026","Make Team Chat obvious",["The Chat inbox now labels Anaesthetic Team plainly as Team chat, explains that it reaches everyone on tonight’s roster, uses team-member wording, and gives New private chat a visible text label.","The staff-coordination notice is shorter and no longer repeats the 14-day retention message, while notification settings are visually quieter beneath the conversations.","Team and private composers now use one glass dock with a plain text field and one send button, clearer placeholder text, cleaner spacing above the tab bar, and no duplicate borders or glow rings."]],["37.89","30 September 2026","A real Chat inbox",["Chat now opens as an inbox with Anaesthetic Team pinned alongside private conversations, instead of embedding the full group conversation above the inbox.","Team and private conversations now open in a dedicated full-height thread with Liquid Glass header and composer chrome, clearer message grouping, unread dividers and cleaner timestamps.","Unread state is now tied to the conversation actually being open, while replies, @mentions, long-press actions, retry/delete behaviour, notification preferences and the staff-coordination safety boundary remain intact."]],["37.88","30 September 2026","Keep confirmed nights ready",["A confirmed seven-nurse arrangement now shows Plan ready on Night when there are no unresolved staffing, allocation or Labour Ward tasks.","Seven-nurse arrangement text remains visible for context but is styled as informational after confirmation instead of as a warning.","Review needed is now reserved for genuine unresolved work, and it still returns automatically if a later change creates a task or requires confirmation."]],["37.87","30 September 2026","Keep shared plans complete",["The Confirm step now hides the primary Confirm and share action once the selected-night plan is already published, including after the allocation view remounts.","The Night and Breaks confirmation hint is shown only while confirmation is actually required, so a completed shared plan no longer looks unfinished.","If staffing, allocations or night-only roles change after publication, the confirmation controls automatically return so the revised plan can be reviewed and shared again."]],["37.86","30 September 2026","Make Breaks faster to scan",["The compact scroll navigation on Changes, Breaks, Chat and Full Roster is taller and uses a clearer 17px title with more breathing room while retaining the neutral content-under-glass treatment.","Break plan now presents First break and Second break as two clearly separated schedule groups with numbered section markers and integrated nurse counts instead of detached count badges.","Break nurse rows are tighter and easier to scan, while the signed-in nurse uses only a slim blue leading marker, subtle tint and compact You badge rather than a heavy blue block.","Labour Ward and Pager notes now sit under a clearer Additional coverage heading and use flatter separated rows instead of another large rounded card.","The Changes Staffing, Allocation and Confirm selector is shorter and visually secondary to Manage this night, with a thin neutral selection lens and blue active text rather than a large filled segment.","The Changes date control gives more width to the selected date on phone layouts by narrowing arrow controls and the staffing summary column.","The bottom destination lens is quieter and nearly borderless so the active icon and text carry selection while underlying content remains more visible."]],["37.85","30 September 2026","Let content lead the interface",["Night no longer creates a floating scroll header; the selected assignment remains the visual anchor while the page scrolls naturally.","Changes, Breaks, Chat and Full Roster now form a slim neutral navigation edge only as their large page heading leaves the viewport, with no duplicated workflow rail or oversized glass capsule.","Roster Management keeps its normal section tabs in the page and replaces them with one compact Liquid Glass section rail only after those tabs scroll away.","Night now uses a more instrument-like dark assignment surface, a clearer Tonight's assignment label, flatter date and overview groups, hairline-separated rows and fewer card-like containers.","Roster Management status and summary content now reads as grouped settings rows instead of nested dashboard cards, while the original section tabs are no longer a second sticky glass layer.","The bottom navigation is clearer and quieter, with less tint and shadow so the moving lens and the content passing underneath provide the visual depth.","Scroll-edge feathering, typography hierarchy, Reduced Transparency, Increased Contrast and Reduced Motion behavior were aligned with the simplified control-plane model."]],["37.84","30 September 2026","Make Liquid Glass respond to touch",["The bottom navigation now illuminates from the finger position during taps and continuous tab drags, while the selected lens subtly brightens and keeps its existing gel-like flex.","The moving destination lens is now a thin light-and-tint overlay inside the parent material instead of inheriting its own second blur, removing the remaining glass-on-glass over-frosting.","Collapsed Changes and Roster Management controls now receive the same localized touch illumination inside their existing glass plane, preserving the single-material hierarchy.","Touch energy follows the pointer while it moves and disappears cleanly on release or cancellation, without changing navigation, swipe, roster, staffing, authentication, realtime or update behavior.","Reduced Transparency disables the light bloom and Reduced Motion removes its elastic expansion, while browser smoke coverage now guards the new touch-response and single-layer lens states."]],["37.83","30 September 2026","Make floating chrome behave like Liquid Glass",["Floating headers, workflow rails, Roster Management tabs, bottom navigation, Chat chrome and the update prompt now use a much clearer neutral Regular material, allowing shapes and colour from scrolling content to remain visible through the glass.","The compact header now materializes by progressively strengthening blur, saturation, contrast, depth and the scroll-edge dissolve instead of relying on a simple whole-surface fade.","Changes and Roster Management use a single spring-driven selected lens inside the collapsed glass rail, while the bottom navigation lens subtly stretches and compresses during taps, drags and page swipes.","Chat now avoids glass on glass: the outer composer remains the floating material and the input control becomes a thin translucent overlay, while larger account and release sheets use a deliberately thicker Regular material.","Reduced transparency, increased contrast, reduced motion and unsupported-backdrop fallbacks remain intact, and browser coverage now guards transparency, scroll-edge treatment, moving lenses and the single-layer composer."]],["37.82","30 September 2026","Merge contextual controls into glass chrome",["Changes now carries Staffing, Allocation and Confirm inside the collapsed glass header, with the selected step staying in sync with the existing workflow controls.","Roster Management now folds Overview, Publish, Team, Access and Data into the same collapsed glass slab, while the in-page section rail scrolls away naturally instead of forming a second sticky bar.","The compact chrome grows continuously as its contextual rail appears, with blur and saturation increasing with scroll depth so the transition feels attached to the user’s gesture rather than switching abruptly.","Night keeps the signed-in nurse’s assignment visible with the selected date at the trailing edge, while Breaks and Chat retain their personal and live context without changing roster, staffing, authentication, realtime or update-activation behaviour.","Browser coverage now verifies the contextual Changes and administrator rails, their active-state synchronisation and the single-slab management layout."]],["37.81","30 September 2026","Restore unified floating glass",["Roster Management’s Overview, Publish, Team, Access and Data rail is translucent again, with stronger blur, saturation, edge highlights and a more transparent selected segment so content visibly travels underneath it while scrolling.","The scroll-linked compact header, floating bottom navigation, Chat composer and update card now share one optical glass material instead of using slightly different translucent treatments.","Floating chrome gains subtle edge refraction and specular highlights while solid clinical content remains opaque for legibility and hierarchy.","Reduced-transparency and unsupported-browser fallbacks remain solid and accessible, and browser coverage now verifies that the major floating surfaces are genuinely translucent rather than opaque."]],["37.80","30 September 2026","Fix persistent update banner",["The update card now has an explicit high-priority hidden state, fixing the CSS conflict that kept it visible even after the update logic correctly marked Night Roster as already up to date.","The passive update card is now guaranteed to stay off Changes, Breaks and Chat even if a stale visibility class remains on the element.","Browser coverage now verifies both dismissal and Night-only visibility so this specific stuck-banner regression cannot silently return."]],["37.79","30 September 2026","Fix PWA update state",["The app now asks both the active and waiting service workers for their real cache version, so a page that already shows the new interface is described as finishing installation rather than incorrectly claiming that a new version is available.","The update banner is cleared as soon as the accepted service worker takes control, with a timed recovery path that reloads once if the normal controller-change event is missed.","Choosing Later is now scoped to the specific waiting version, so deferring one release cannot accidentally suppress a later update during the same app session.","Same-version component refreshes and partially installed current releases now have distinct, accurate update copy while the explicit ACTIVATE_UPDATE approval flow remains unchanged."]],["37.78","30 September 2026","Add scroll-linked glass and night-shift depth",["Night, Changes, Breaks, Chat, Roster and Roster Management now gain a scroll-linked compact glass header that fades and settles continuously as content moves underneath it, while reduced-motion and reduced-transparency preferences remain respected.","Roster Management now uses a sticky frosted section rail plus grouped status, operational and system-health rows instead of a dashboard of repeated tiles.","The PWA update prompt is smaller, theme-aware and translucent, with a quieter Later action and a clear blue Update action while preserving the existing user-approved service-worker activation flow.","The black personal assignment hero keeps its signature dark identity but gains restrained blue light, inner depth, richer shift-token treatment, scan icons and a subtle Motion entrance.","Chat composer and management chrome now share the same content-under-glass material language so scrolling feels more continuous without adding glass to clinical content surfaces."]],["37.77","30 September 2026","Finish the mobile craftsmanship pass",["Night now has the same clear destination identity as Changes, Breaks and Chat, while its Tonight board relies on spacing and hairline separators rather than extra shadow and card furniture.","Changes now presents Absences and Overtime as one grouped staffing surface, removes duplicated no-record messages and keeps exceptional editing in focused Motion sheets.","Breaks now uses flat nurse rows inside one schedule surface, with blue reserved for the signed-in nurse and interaction rather than decorative section colour.","Chat now keeps notifications after conversations, fixes the masthead composition and renders team messages as true left/right conversation bubbles with lighter metadata and a sticky native-style composer.","Shared chrome gains consistent account and administrator controls, tighter radii, restrained tactile feedback, a lighter Motion tab indicator and a more intentional dark-mode treatment for night-shift use."]],["37.76","30 September 2026","Unify the primary app shell",["Changes, Breaks and Chat now share Mater Dei institutional branding, section-title rhythm and selected-night styling with Night, removing the previous sense that each destination belonged to a different interface.","Night now groups team state, allocation, the signed-in nurse’s break and selected-night activity into one Tonight board, replacing the loose lower-page text with clear operational rows and a deliberate no-changes state.","Changes now keeps absence and overtime forms out of the way during a normal night: compact staffing summaries open focused Motion bottom sheets only when a user chooses to add or edit a staffing change, with blue primary actions.","Break headings and counts are now neutral, while blue is reserved for the signed-in nurse and interaction, removing the leftover purple and teal section colours.","Primary date navigators, spacing, hierarchy and status treatment are more consistent across Night, Changes and Breaks without changing roster logic, shared-data behaviour, swipe navigation, accessibility or PWA update semantics."]],["37.75","30 September 2026","Polish the night shift interface",["Changes now uses a tighter selected-night bar, calmer step control, compact staffing editors and lower-noise empty states, while preserving the existing Staffing → Allocation → Confirm workflow and every shared-data action.","Breaks now presents First break and Second break as one coherent schedule board, uses a subtle blue personal marker instead of the previous heavy outline, and keeps Labour Ward/Pager notes readable without truncating the operational text.","Chat now presents team messages as familiar conversation bubbles, uses a lighter composer and places notification management behind a secondary disclosure so conversations remain the primary content.","Roster management now fits all five sections on a phone without clipped tabs and compresses overview/status surfaces into a clearer operational summary.","Shared React and Tailwind primitives now use quieter borders, tighter rows and more restrained glass, while the floating navigation is slimmer and keeps the existing continuous swipe, reduced-motion, dark-mode and accessibility behaviour."]],["37.74","29 September 2026","Unify the clinical app experience",["Changes now behaves as a guided task flow: automatic steps recede, unresolved allocation work becomes the clear focus, staffing forms use quieter grouped surfaces, and exceptional states communicate through wording and hierarchy rather than colour alone.","Breaks is now an operational duty board with the signed-in nurse’s own break as the primary focus, compact selected-night context, a concise staffing readout and one coherent team break plan.","Chat now prioritises conversations over settings, uses a calmer familiar transcript and composer, keeps private conversations immediately accessible, and moves notification preferences into a secondary position without changing chat, push or realtime behaviour.","The signed-in app now shares neutral graphite and cool surfaces with restrained Apple-style blue interaction cues, removes the remaining teal accents, standardises typography, spacing, grouped rows, empty states, segmented controls and press feedback, and keeps glass limited to floating navigation and transient chrome.","Roster date controls now describe human context such as the current or past roster night, dark mode is treated as a primary night-shift environment, and the existing continuous swipe navigation, reduced-motion support and accessibility behaviour are preserved."]],["37.73","29 September 2026","Unify Night and the professional profile",["Night now reads as one deliberate flow from selected date to personal assignment, team state, allocation and recent activity, reducing disconnected labels, separators and floating actions.","The personal assignment combines identity, role, colleague, duty time, break and the contextual night-situation action into one focused surface while preserving existing roster and swipe behaviour.","Team status and Team allocation are grouped into one compact disclosure area, with full-roster access placed inside the allocation context and a quieter recent-activity empty state.","The account profile now uses a professional identity-first layout with a larger editable photo, preferred name and professional title, clear private roster highlighting, and a distinct verified account identity section.","The Night and profile experiences use neutral graphite and cool surfaces with restrained blue interaction cues, while light, dark and automatic appearance, accessibility and all existing account actions remain intact."]],["37.72","29 September 2026","Refine Night with Apple-style clarity",["Night now uses a graphite and cool-neutral visual system with restrained blue reserved for actions, selected navigation and meaningful status instead of the previous teal treatment.","The personal assignment is the clear focal point, with role, colleague, duty time and break organised through calmer system typography, spacing and progressive disclosure.","The redundant header appearance shortcut has been removed; Light, Automatic and Dark remain available in Account settings, while the existing swipe gestures and clinical roster behaviour stay unchanged."]],["37.71","29 September 2026","Night screen prototype",["The broad 37.70 presentation treatment has been rolled back on Changes, Breaks, Chat, Account and the full roster, while the existing app stack and behavior remain intact.","Night now puts its selected date, personal role, working period, break and colleague ahead of a concise staffing state.","Team allocation is available on demand below the brief, with a calmer light and dark treatment and the existing navigation gestures."]],["37.70","28 September 2026","Read the night at a glance",["The Night screen leads with a distinct assignment panel and a concise staffing brief instead of statistic tiles.","The full roster reads as a searchable ledger, with clearer role and exception details.","Navigation, Changes, Breaks, Chat, account and first-use surfaces share a quieter visual rhythm, with clinical content kept solid."]],["37.69","28 September 2026","Make team chat easier to reach",["The team chat header takes less space while preserving the roster member context.","The message viewport remains scrollable and leaves more room for the composer on phones.","Chat delivery, privacy controls, and navigation gestures remain unchanged."]],["37.68","28 September 2026","Bring the break plan closer",["Your break is easier to read without repeating the staffing count in the personal card.","The selected night uses a compact control while the shared summary carries the staffing count and Labour Ward state.","The break plan starts higher on phone screens without changing any break or allocation rule."]],["37.67","28 September 2026","Simplify account and release history",["The profile editor uses a shorter introduction and a more compact photo and field layout.","Appearance, app help, and sign-in controls remain grouped with clearer spacing.","Version history distinguishes the current update from earlier releases without removing any entries."]],["37.66","28 September 2026","Bring Changes decisions into view",["The selected night and staffing count now share a compact context card.","The Staffing, Allocation, and Confirm steps are easier to scan without taking over the phone screen.","The live state and decisions remain visible while the underlying workflow and roster rules stay the same."]],["37.65","28 September 2026","Clarify the Night allocation dashboard",["The personal Night card gives the role and assignment details more room to scan.","On-duty time, break, and context now share a compact summary strip.","The team overview uses calmer labels and a simpler surface without changing roster calculations."]],["37.64","28 September 2026","Fix cramped roster and break summaries",["Full-roster cards no longer squeeze into a nested desktop grid.","The automatic Labour Ward break status stays on one readable line in the phone summary.","These changes affect layout only; the selected night and break calculations remain the same."]],["37.63","28 September 2026","A clearer full-roster view",["The full roster shows how many nights match the search and makes each night’s live plan easier to scan.","Search and staffing filters now use the shared light and dark controls, with clearer focus and touch targets.","The full-roster cards now use the correct responsive and dark-mode styles."]],["37.62","28 September 2026","Clearer app guidance and updates",["Install and version-history dialogs now use the same clear surfaces and headings as the rest of the app.","Update details keep their separate Later and Update now choices in a more readable sheet.","Installation and version-history dialogs now identify their title and introduction to screen readers."]],["37.61","28 September 2026","A clearer way into Night Roster",["On phones, the sign-in form appears sooner beneath a compact hospital and app introduction.","Onboarding now announces its step count and focuses each new page heading for keyboard and screen-reader navigation.","Sign-in fields and first-use screens use the shared light and dark presentation surfaces."]],["37.60","28 September 2026","Clearer roster management on phones",["Roster management sections now have a scrollable navigation strip with larger touch targets and a clear selected state.","Account rows give long names and email addresses space on narrow phones, with the account action on its own line.","Administrator content uses the same calm surfaces and spacing as the rest of the redesigned app."]],["37.59","28 September 2026","Account and settings, clearly grouped",["Account now groups personal details, appearance, app help and passkeys in a calmer sheet, with a centred dialog on larger screens.","The approved account identity is distinct from preferred profile details and the locally highlighted roster name.","Photo, profile and passkey controls have clearer spacing, touch targets and saving feedback.","Profile privacy, password access, shared roster identity and deliberate PWA update approval remain unchanged."]],["37.58","28 September 2026","Clearer Chat conversations",["Private chats now show clearer unread counts, message previews and times in a more scannable list.","Message actions have a visible control as well as the existing long-press and keyboard actions, and recent messages sit closer to the composer.","The new-message sheet can search current roster members, with registration status shown plainly rather than fading people out.","On larger screens, an empty conversation has a clear starting point instead of an inactive composer.","Chat delivery, privacy, notification preferences, roster calculations and deliberate PWA update approval remain unchanged."]],["37.57","27 September 2026","Clearer Chat connection notices",["Chat connection and service notices now have clear error or update labels beside the conversation.","The existing live text remains visible if the optional presentation component cannot load.","Message delivery, unread state, notification preferences and deliberate PWA update approval remain unchanged."]],["37.56","27 September 2026","Clearer Changes save feedback",["Saving and successful sharing have clear status labels in the Confirm step.","Offline guidance, conflicts and errors remain visible next to the confirmation action with explicit next steps.","The plain live message remains available if the optional presentation component cannot load.","Existing validation, shared writes, retry and deliberate PWA update approval remain unchanged."]],["37.55","27 September 2026","Clearer confirmation review",["The Confirm step shows changed assignments in grouped rows, with the complete plan available when you expand it.","An unresolved allocation is clearly flagged before confirmation, and a reason remains visible alongside the changes.","The Changes heading and step guide now scroll away so they do not cover the confirmation review.","The previous preview remains available if the optional presentation component cannot load.","Staffing and allocation validation, shared confirmation, roster calculations and deliberate PWA update approval remain unchanged."]],["37.54","27 September 2026","Guided Changes workflow",["A guided Staffing, Allocation and Confirm control shows the current step, pending decisions and what to do next.","Staffing records and selected-night allocation choices use simpler grouped rows and larger controls on phones.","The original step controls remain available if the optional presentation component cannot load.","Existing staffing validation, allocation rules, confirmation, shared data and explicit update approval remain unchanged."]],["37.53","27 September 2026","Personal-first interface foundation",["Your allocation now leads the Night screen, followed by the selected night, staffing summary, live team and recent activity.","Breaks shows a personal first or second break summary above the full team plan, while pending allocations remain clearly provisional.","Night, Changes, Breaks, Chat, Account, authentication, dialogs and update surfaces share calmer spacing, solid information surfaces and restrained glass for navigation.","The presentation styles now have one ordered source instead of seven separate cascading override files, with existing React view models and roster actions preserved.","The current release dialog is titled What’s new, with the complete version history still available from Account.","The roster rotation, staffing and allocation rules, Supabase access, push and chat delivery, and explicit PWA update approval flow remain unchanged."]],["37.52","27 September 2026","React interface system",["A reusable React interface system now provides consistent pressable controls, grouped lists, adaptive surfaces, glass surfaces, avatars, badges, empty states, fields and loading primitives across the app.","Motion now powers shared-layout selection in the Appearance control and consistent spring press feedback instead of each screen implementing interaction feedback separately.","Tailwind container queries let profile fields and break-plan layouts adapt to the space available to each component rather than relying only on whole-screen breakpoints.","Chat private conversations and member selection now use a cleaner grouped-list hierarchy, while the message composer is a single floating Liquid Glass capsule with preserved keyboard, character-count and send behaviour.","Changes records, allocation rows, history and staffing forms now use the shared React component system while preserving the existing workflow, identifiers and staffing logic.","Night and Breaks now use the shared Motion pressable and surface primitives for more consistent touch feedback without changing roster calculations or clinical rules.","Tailwind dark-mode utilities are now tied to Night Roster’s own Light, Automatic and Dark setting so React components follow the selected in-app appearance reliably.","Authentication, Supabase data, roster calculations, staffing safety rules, Chat delivery, notifications and the installed PWA identity are unchanged."]],["37.51","27 September 2026","Night interface refined",["Your Night is now a dedicated assignment hero with a clearer identity row, role treatment, compact facts and a lighter contextual action.","Night Summary is one integrated four-part information rail instead of a two-by-two dashboard card grid.","Night Situation now uses compact grouped roster rows with semantic role accents instead of oversized grey cards.","Five-nurse mode now sits in the same visual hierarchy as the rest of Night rather than appearing as a separate heavy card.","Recent Activity is presented as a cleaner grouped timeline with lighter metadata and less visual boxing.","The floating bottom navigation is slimmer and more translucent, with a clearer moving Liquid Glass selection lens.","Night header spacing and controls are more compact while preserving 44-pixel touch targets, safe areas and dark-mode readability.","Roster calculations, staffing rules, authentication, Supabase data, Chat and notifications are unchanged."]],["37.50","27 September 2026","Liquid Glass mobile experience",["A new Liquid Glass application shell gives navigation and key controls a floating, translucent material layer while keeping clinical roster content solid and readable.","Night, Changes, Breaks and Chat now share one persistent bottom navigation bar with a moving selection lens and physically connected page transitions.","Horizontal navigation follows the finger directly, uses distance and velocity when settling, preserves page scroll positions and more reliably distinguishes horizontal swipes from vertical scrolling.","Night presents staffing status and personal allocation with a clearer hierarchy, fewer nested cards and more compact native-style roster rows.","Changes uses a more cohesive date and staffing context, a moving workflow selector and calmer grouped forms for staffing and allocation tasks.","Breaks uses the same date language and a cleaner scan-first presentation for first break, second break and Labour Ward or Pager duties.","Chat now gives conversations greater visual priority while notification preferences and secondary settings are quieter and more structured.","Header controls, sheets, dark mode, safe-area handling, reduced-motion behaviour and touch targets have been refined for installed mobile use.","Motion and gesture work is concentrated on transform-based interactions so the interface feels more responsive without changing authentication, Supabase data or roster calculations."]],["37.49","26 September 2026","Compact roster layout restored",["Night, Changes and Breaks no longer render a second nested card layer inside the existing clinical surfaces.","Personal assignment, staffing records, allocation rows, break groups and recent activity use the established compact mobile layout again.","The React migration remains in place, while the existing Apple-style spacing and clinical hierarchy once again control presentation.","Roster calculations, Supabase data, authentication, Chat, notifications and clinical decision rules remain unchanged."]],["37.48","26 September 2026","Roster startup restored",["Roster startup no longer waits for a React-owned staffing field before the Changes component has mounted.","The same repair restores the read-only saved-roster path when the shared connection is unavailable.","A startup regression check now covers the delayed Changes component mount.","Roster calculations, staffing workflows, Supabase data, authentication, Chat and clinical decision rules remain unchanged."]],["37.47","26 September 2026","React-powered version history",["The App Updated panel and complete Version History are now an isolated React and TypeScript component loaded only when release notes are requested.","The existing version archive, Latest and Previous updates navigation, light and dark styling, accessibility labels and reduced-motion behaviour are preserved.","If the optional component cannot load, the complete escaped HTML release history remains available instead of leaving an empty dialog.","Roster calculations, staffing workflows, Supabase data, authentication, Chat, swipe navigation and the installed PWA identity remain unchanged."]],["37.46","25 Sep 2026","Reliable swiping over Chat messages",["Horizontal navigation can now begin directly on a Chat message as well as on blank transcript space. Message rows remain keyboard-focusable and keep their long-press actions, but focusability no longer makes the whole message a forbidden swipe-start area.","This fixes the specific missed gestures visible in the touch recording, where the finger travelled horizontally across message text while the Chat page stayed still, then worked when the same gesture started from nearby blank space.","Buttons, links, inputs, text areas, editable fields and other explicit controls remain protected from accidental navigation, and vertical scrolling is unchanged.","The viewport-pinned page track, roster logic, Supabase data, authentication, staffing rules and clinical workflows are unchanged."]],["37.45","25 Sep 2026","More reliable swipe starts",["Horizontal page swipes now start from normal empty space inside status rows, workflow strips, date controls and Chat list containers instead of treating those whole regions as blocked. Actual buttons, links, inputs, text areas and other interactive controls remain protected from accidental navigation.","The gesture direction lock now tolerates the small diagonal wobble that commonly happens at the start of a thumb swipe, while clearly vertical movement still hands control back to normal page scrolling.","A swipe can therefore begin from far more of the visible page without having to repeat the gesture or move the finger to a different vertical position.","The viewport-pinned page track, roster logic, Supabase data, authentication, staffing rules and clinical workflows are unchanged."]],["37.44","25 Sep 2026","Stable native page swiping",["Each primary screen now owns its complete top chrome while it moves, so the Night header travels with the Night page instead of appearing or disappearing after the horizontal transition.","Incoming screens are staged at their own saved vertical scroll position, preventing the blank-screen jump seen when moving between tabs that were previously scrolled to different heights.","Primary view geometry now includes the full screen gutters and uses one anchored horizontal track, keeping pages attached edge-to-edge while dragging, reversing direction or settling.","Roster calculations, Supabase data, authentication, staffing rules and clinical workflows are unchanged."]],["37.43","25 Sep 2026","Solid continuous page flow",["Night, Changes, Breaks and Chat now move as solid full-size pages on one horizontal track, so adjacent screens meet edge-to-edge instead of fading or scaling through each other.","The transparency and scale morph from 37.42 has been removed because it could make two screens visually overlap during a swipe. Both the outgoing and incoming page remain fully opaque throughout the transition.","Swipe settling, bottom-tab taps and long bottom-bar drags now use the same 260 ms horizontal easing, with the tab selector synchronised to the page movement.","Vertical scrolling, protected controls, Chat interactions, reduced-motion behaviour, roster calculations, Supabase data and authentication are unchanged."]],["37.42","25 Sep 2026","Fluid screen transitions",["Night, Changes, Breaks and Chat now hand off as one continuous slide instead of snapping when the destination becomes active.","The outgoing screen subtly scales and fades while the incoming screen settles into place, creating a restrained morph effect that stays tied to the direction of travel.","Tapping a bottom tab and releasing a long bottom-bar drag now use the same screen transition as direct page swipes, while the selected tab indicator moves in sync.","Reduced-motion users still receive an immediate, non-animated view change. Roster calculations, Supabase data, authentication and staffing rules are unchanged."]],["37.41","25 Sep 2026","Smoother continuous swiping",["The bottom tab selector now follows one continuous drag across the entire bar, so a single gesture can move from Night through Changes and Breaks all the way to Chat before settling on the nearest tab.","Screen swipes now lock onto the direction once the gesture is clearly horizontal, so small diagonal finger movement no longer cancels a swipe halfway through. The page and bottom selector stay synchronised through the drag.","Horizontal navigation is now available from Chat as well as Night, Changes and Breaks when the gesture begins on safe noninteractive space. Message areas, composers, buttons, forms, workflow controls, dialogs and screen-edge gestures keep their own interactions.","The bottom bar uses a more stable opaque glass layer so content underneath does not read as a second or broken bar. Roster calculations, Supabase data, authentication and the safe PWA update flow are unchanged."]],["37.40","25 Sep 2026","Pages that move with your swipe",["The main Night, Changes and Breaks pages now move under your finger during a horizontal drag, with the adjacent page entering from the side you are moving toward.","Page gestures now use natural direct-manipulation direction: drag the page left to advance to the tab on the right, or drag it right to return to the tab on the left. The bottom tab slider keeps its existing direct behavior.","Short page drags settle back into place. Vertical scrolling, forms, workflow controls, dialogs, Chat conversations and screen-edge gestures keep their existing interactions, and reduced-motion settings avoid animated settling.","The verified roster, Supabase data, authentication and safe PWA update flow are unchanged."]],["37.39","25 Sep 2026","A tab slider that follows your finger",["The selected highlight in the bottom bar now tracks a horizontal drag across the bar or a noninteractive part of Night, Changes and Breaks, then settles on the chosen tab. Short drags return to the current tab.","Directions match the visible slider: swipe right to the tab on the right, or left to the tab on the left. From Night, swipe right for Changes; from Changes, swipe left for Night.","Vertical scrolling, forms, workflow buttons, dialogs, Chat conversations and screen-edge gestures retain their existing behavior. Reduced-motion settings show the destination without an animated spring; tabs still work by tap and keyboard.","The verified roster, Supabase data and the safe PWA update flow are unchanged."]],["37.38","25 Sep 2026","Swipe between screens",["Horizontal swipes now work across the noninteractive content of Night, Changes and Breaks as well as the bottom tab bar, moving one tab at a time.","The gesture uses real touch events so the browser does not cancel it during a swipe. Vertical scrolling, form controls, dialogs, selected text and Chat conversations keep their own interactions; the tabs remain available for every destination.","This corrects the tab-bar swipe introduced in 37.36 that did not respond to normal phone gestures. The roster engine, staffing rules, Chat, shared data and safe update flow remain unchanged."]],["37.37","25 Sep 2026","Clearer screen guidance",["The Staffing and Breaks information sheets now render their guidance in a small React and TypeScript component when opened, with Tailwind CSS v4 utilities scoped to that content.","Motion gives the help items a brief reveal in standard mode and shows them immediately when reduced motion is preferred. The existing native dialog, close control and light and dark styles remain in place.","Breaks guidance now describes a provisional plan accurately instead of referring to retired copy and email actions.","If the optional component cannot load, the escaped HTML guidance stays available. The help chunk is included in the PWA shell for offline use, while staffing decisions, Chat, Supabase and updates continue through their existing paths."]],["37.36","25 Sep 2026","Responsive React navigation",["The signed-in tab bar is now a reusable React and TypeScript component, loaded after access is authorised. Night, Changes, Breaks and Chat keep their familiar positions, live badges and keyboard controls.","A short horizontal touch swipe across the tab bar moves to the adjacent destination. Taps use restrained Motion feedback that follows the device’s reduced-motion setting.","The existing HTML navigation stays usable if the extra component cannot load. Tailwind CSS v4 utilities remain scoped without resetting clinical styles; light and dark chrome, Supabase access, roster decisions, Chat and safe PWA updates continue as before.","The new component and its separate build asset give the app a tested path for moving stable interface regions incrementally. Clinical screens and their data still run through the existing roster engine."]],["37.35","25 Sep 2026","What the new app foundation makes possible",["Now in place: Vite builds the same installable Night Roster PWA from pinned React, TypeScript, Tailwind CSS v4 and Motion for React dependencies. The launch motto is the first small React region; Night, Changes, Breaks and Chat still use their existing working code.","Now in place: TypeScript checks the new frontend code during every build. Tailwind utilities are available with a prefix and without a global reset, so future interface work can share responsive styles without changing the current clinical screens.","Now in place: Motion powers a restrained launch reveal that respects reduced-motion settings. The custom service worker also caches the new build assets while retaining the same app identity, push notifications, offline shell and choice to install updates.","Possible next: migrate one stable screen at a time into reusable React components, improve consistent mobile and desktop layouts and light and dark themes, and load larger sections only when needed. These screens have not yet been migrated.","Possible next: add carefully tested touch gestures, smoother sheets and purposeful spring transitions using Motion, with reduced-motion alternatives. These interactions are not included in this release, and a 120 Hz frame rate cannot be guaranteed on every device.","The 138-night rotation, staffing safety rules, Supabase authentication and data, chat, Realtime and notification permissions remain unchanged. The app continues to be installed and updated from the same web address without an app store."]],["37.34","24 Sep 2026","Launch style cleanup",["Removed duplicated style rules and the superseded CSS animation for the React-owned launch motto.","The launch motto remains visible if the optional React module has not loaded, while reduced-motion behavior and the existing roster and notification flows remain intact."]],["37.33","24 Sep 2026","Application shell foundation",["The existing PWA now ships from a pinned production build while keeping the same installed identity, roster engine, sign-in, chat, notifications and shared backend.","The static launch motto is the first small React region; its gentle reveal respects reduced-motion settings.","The custom service worker includes new fingerprinted build assets while preserving the update choice, push delivery and offline shell rules."]],["37.32","24 Sep 2026","Premium PWA experience",["The operating-system splash now hands off to the exact Night Roster app icon on the same first-paint background, so the static startup frame appears to come alive instead of jumping into a second unrelated loader.","Installation guidance now adapts to iPhone, iPad, Android and already-installed mode, with Home Screen installation presented as a one-time step and future releases handled by the PWA update system.","Installed-app badges now reflect unread Chat and administrator attention where the platform supports the Badging API, while background notifications can show a generic badge until the exact count is refreshed.","Night and Chat are available as app shortcuts on supporting platforms, notification deep links remain routed to the exact conversation, roster night or administrator access screen, and standalone mode hides browser-only install actions.","Minor releases can use quiet automatic-on-reopen updates while important releases retain the full review-and-update sheet; safe areas, keyboard handling, first-paint theme and touch chrome have been refined without changing roster or Supabase behaviour."]],["37.31","24 Sep 2026","Cinematic launch and refined onboarding",["Cold launch now uses a staged cinematic reveal that follows the real roster-loading state instead of adding a fake loading delay, then hands off smoothly into the signed-in app or sign-in screen.","First-use onboarding now uses calmer directional transitions, richer visual hierarchy and a dedicated current Chat page covering Team chat, private messages, @mentions, replies, privacy-safe notifications and 14-day retention.","Existing users receive the refreshed Chat introduction once, while replaying the guide from Account still shows the complete onboarding journey.","Normal tab switching no longer animates the whole view, keeping Night, Changes, Breaks and Chat stable while motion is reserved for launch, onboarding, sheets and touch feedback.","Buttons, inputs, grouped surfaces, dark mode and persistent navigation receive a restrained native-style polish with full reduced-motion fallbacks."]],["37.30","24 Sep 2026","Reliable chat sends and clearer night wording",["Team and private chat sends no longer fail because reply validation recursively re-enters the chat message policy. Successfully saved messages stay sent even if read-state or push-notification housekeeping has a separate problem.","Your night now says Tonight, Current night, Next night or Selected night according to the date actually being viewed, so a future roster night is no longer described as tonight.","Changes, allocation, break guidance and night-only role wording now refer to the selected night instead of assuming the selected date is today.","The verified roster rotation, staffing rules, breaks, chat privacy, 14-day retention and notification preferences remain unchanged."]],["37.29","24 Sep 2026","Operational alerts and focused chat",["Roster changes can now send optional privacy-safe notifications that open the affected night directly.","Administrators get a compact attention badge for access requests, selected-night actions and roster publication, plus a privacy-safe alert when someone requests access.","Anaesthetic Team now supports @mentions with targeted alerts, while Team and private chats can reply to a specific message with a compact quote.","Chat messages are retained for 14 days and then removed automatically by the server.","A lightweight real-browser smoke suite now checks mobile navigation and dark mode alongside the existing regression tests."]],["37.28","24 Sep 2026","Cleaner Night and Admin controls",["Night and Breaks now focus on the live roster information itself, with the repeated copy-briefing, copy-breaks and email-roster controls removed.","Roster management keeps the useful Publish, Team, Access and Data sections, while Overview no longer repeats those same destinations as a second row of shortcut buttons.","Unused frontend code that existed only for the removed copy and email actions has been retired; roster calculations, staffing changes, breaks, chat, notifications and Supabase data remain unchanged."]],["37.27","24 Sep 2026","Lean maintenance cleanup",["The installed app now reuses the same reviewed icons for standard and maskable purposes instead of shipping duplicate image files, reducing unnecessary app-shell data without changing appearance.","Outdated repository audit snapshots and superseded setup records were removed from the current source tree while remaining available in Git history.","Roster calculations, staffing changes, breaks, Team Chat, notifications, authentication, Supabase data and the complete in-app version history are unchanged."]],["37.26","24 Sep 2026","A more complete Team Chat",["Chat now separates days and unread messages clearly, keeps your reading position when new messages arrive and offers a New message shortcut instead of pulling you to the bottom.","Messages that fail to send stay visible with Retry, while message actions let you copy text and delete your own recently sent message without adding editing, reactions or other social features.","Notification controls now show device status, explain blocked permissions, let you mute Anaesthetic Team for one hour, for tonight or until you turn it back on, and let you remove old notification devices.","Private-chat availability updates live as roster members register, notification taps open the relevant conversation, and Chat uses a compact overview request so roster startup remains independent.","Onboarding is shorter, and administrators get privacy-safe health information for roster sync, chat registration and notification delivery without seeing private messages or notification endpoints."]],["37.25","24 Sep 2026","Team chat & notifications",["Anaesthetic Team provides one shared group chat for roster discussion, with private one-to-one conversations between registered roster members.","Optional message notifications can alert you to new group or private messages when Night Roster is closed or in the background.","Notification previews protect chat privacy by showing that a new message arrived without displaying the message text on the lock screen.","Chat remains separate from roster changes: any agreed swap or change must still be entered through the existing roster functions."]],["37.24","24 Sep 2026","Team chat & notifications",["Anaesthetic Team provides one shared group chat for roster discussion, with private one-to-one conversations between registered roster members.","Optional message notifications can alert you to new group or private messages when Night Roster is closed or in the background.","Notification previews protect chat privacy by showing that a new message arrived without displaying the message text on the lock screen.","Chat remains separate from roster changes: any agreed swap or change must still be entered through the existing roster functions."]],["37.23","24 Sep 2026","Team chat",["Anaesthetic Team adds one permanent group conversation for active authorised roster users, plus private one-to-one chats between registered members.","Chat messages are plain text only and never alter the roster; agreed swaps still have to be entered separately through the existing roster functions.","Private conversations and sender identity are protected by Supabase Row Level Security, while the chat directory exposes names only and never email addresses.","Chat loads recent messages only when opened, paginates older messages and uses its own Realtime channel so Night, Changes and Breaks remain independent."]],["37.22","24 Sep 2026","Team chat",["Anaesthetic Team adds one permanent group conversation for active authorised roster users, plus private one-to-one chats between registered members.","Chat messages are plain text only and never alter the roster; agreed swaps still have to be entered separately through the existing roster functions.","Private conversations and sender identity are protected by Supabase Row Level Security, while the chat directory exposes names only and never email addresses.","Chat loads recent messages only when opened, paginates older messages and uses its own Realtime channel so Night, Changes and Breaks remain independent."]],["37.21","24 Sep 2026","Team chat",["Anaesthetic Team adds one permanent group conversation for active authorised roster users, plus private one-to-one chats between registered members.","Chat messages are plain text only and never alter the roster; agreed swaps still have to be entered separately through the existing roster functions.","Private conversations and sender identity are protected by Supabase Row Level Security, while the chat directory exposes names only and never email addresses.","Chat loads recent messages only when opened, paginates older messages and uses its own Realtime channel so Night, Changes and Breaks remain independent."]],["37.20","24 Sep 2026","Team chat",["Anaesthetic Team adds one permanent group conversation for active authorised roster users, plus private one-to-one chats between registered members.","Chat messages are plain text only and never alter the roster; agreed swaps still have to be entered separately through the existing roster functions.","Private conversations and sender identity are protected by Supabase Row Level Security, while the chat directory exposes names only and never email addresses.","Chat loads recent messages only when opened, paginates older messages and uses its own Realtime channel so Night, Changes and Breaks remain independent."]],["37.19","24 Sep 2026","Team chat",["Anaesthetic Team adds one permanent group conversation for active authorised roster users, plus private one-to-one chats between registered members.","Chat messages are plain text only and never alter the roster; agreed swaps still have to be entered separately through the existing roster functions.","Private conversations and sender identity are protected by Supabase Row Level Security, while the chat directory exposes names only and never email addresses.","Chat loads recent messages only when opened, paginates older messages and uses its own Realtime channel so Night, Changes and Breaks remain independent."]],["37.18","24 Sep 2026","A cleaner sign-in screen",["Night Roster keeps the two simple sign-in routes: approved work email and Google.","The Google action is now centred and presented as one clear Apple-style secondary sign-in choice rather than part of a multi-provider grid.","Microsoft and Apple sign-in remain intentionally absent, so there are no unused or paid-provider options on the login screen.","Authentication rules, access requests, roster permissions and shared data are unchanged."]],["37.17","24 Sep 2026","Request access with Google",["Existing approved members continue to sign in normally.","A new Google user who is not yet approved now creates a pending access request without seeing roster data.","Roster administrators can approve or reject pending requests from Authorised accounts.","Approved requests become normal member accounts; administrator access is never granted automatically."]],["37.16","24 Sep 2026","Sign in with Google",["Approved roster members can now choose Google sign-in from the Night Roster login screen.","Google returns to the existing Night Roster URL after authentication, then the same approved-email check runs before roster data opens.","Only Google is shown for social sign-in at this stage, so no unconfigured provider is presented to users.","Email and password, password reset, passkeys, roster calculations, staffing, allocations, Pager, Reliever and database permissions remain unchanged."]],["37.15","23 Sep 2026","Private device data leaves with you",["Signing out, losing approved access or reaching an invalid session now removes the saved offline roster, cached account email and recently entered staff names from that device.","Authentication and database errors now use safe, useful messages without exposing internal provider or database details, and copied diagnostics no longer include the account email address.","The pinned Supabase browser library is protected by a verified integrity hash, while automated checks guard against secret credentials entering deployed files.","A reviewable database migration removes unused anonymous public-schema privileges without relaxing RLS or changing any authenticated roster permission.","The verified rotation, staffing, allocations, Pager, Reliever, installed-PWA identity and interface remain unchanged."]],["37.14","21 Sep 2026","Sign out only on this device",["Signing out now closes only the current browser or installed app session instead of revoking saved sessions on every device.","Realtime and background refresh work are still stopped before the local session is cleared.","Authentication, roster calculations, staffing, allocations, Pager, Reliever, the interface, service-worker update behaviour and database rules remain unchanged."]],["37.13","20 Sep 2026","Smaller download, same roster",["The installed app icons and Mater Dei logo use lossless recompression, preserving every decoded pixel and the existing colour profile while reducing their combined transfer size.","Confirmed obsolete styling left behind by the earlier personal-summary and workflow replacements has been removed without changing current selectors or layout.","Authentication, Supabase requests, service-worker update behaviour, the interface, verified rotation and every staffing or allocation rule remain unchanged."]],["37.12","19 Sep 2026","One clean route into the roster",["A restored sign-in now starts exactly one shared-roster authorisation path instead of allowing the session listener and startup check to request it twice.","Expired saved sessions are renewed once before the protected roster request is retried, without falling into repeated compatibility reads.","The loaded roster becomes interactive before optional private profile and photo details finish loading, while onboarding still waits for those details.","No interface, roster calculation, staffing, allocation, Pager, Reliever, realtime, privacy or database rule has changed."]],["37.11","19 Sep 2026","Seven-nurse role changes now save",["Custom seven-nurse arrangements now pass the atomic database structure check when all seven roles and the required mode are supplied.","An overtime nurse such as Daniel Santucci can be moved into any agreed role, including Reliever or Seventh nurse, while every working nurse remains assigned exactly once.","The verified rotation, seventh-nurse decision workflow, Pager and Reliever rules, staffing calculations and permanent roster remain unchanged."]],["37.10","19 Sep 2026","Seven nurses can be arranged for one night",["The night-only role editor now includes a Seventh nurse role whenever seven effective nurses are working, including named overtime staff such as Daniel Santucci.","The new arrangement remains explicitly night-only, requires every effective nurse exactly once, and keeps the permanent rotation and automatic allocation rules unchanged.","The database upgrade is forward-only and validates seven-role assignments atomically before saving them."]],["37.9","19 Sep 2026","The roster now finishes opening",["The live browser test found that the shared roster was loading successfully, but the Changes allocation control stopped rendering because its staffing plan was not defined.","The allocation control now derives the selected night’s plan before deciding whether confirmation choices should appear, so Night, Changes and Breaks finish opening after sign-in and on restored sessions.","A deterministic seven-nurse render check now covers the exact state that exposed the failure.","No roster calculation, staffing, allocation, Pager, Reliever, five-nurse, realtime, privacy, database schema or write rule has changed."]],["37.8","19 Sep 2026","A clean Android route into the live roster",["Installed Android apps now open the existing protected schema-37 snapshot through a bounded XMLHttpRequest instead of the fetch path that could remain pending after an app update.","The Android request has its own hard deadline and Retry always begins a fresh transport request.","The opening screen no longer presents recovery controls while a normal startup request is still in progress.","No roster calculation, staffing, allocation, Pager, Reliever, five-nurse, realtime, privacy, database schema or write rule has changed."]],["37.7","19 Sep 2026","A second independent route into the roster",["Android now opens through sequential authorised roster reads, avoiding the one-request startup transport that remains pending on the affected Samsung browser.","Every compatibility read has an application-level deadline, while other devices retain the protected snapshot with the same independent deadline and automatic fallback.","Try again can no longer wait forever for an abandoned startup promise, and the opening message identifies when the compatibility route is being used.","No roster calculation, staffing, allocation, Pager, Reliever, five-nurse, realtime, privacy, database schema or write rule has changed."]],["37.6","18 Sep 2026","Startup requests that reach the roster reliably",["The opening snapshot now uses a bounded authenticated web request instead of the client wrapper that failed to dispatch on the affected Samsung browser.","The request still calls the same protected schema-37 function, preserving account access, privacy and one internally consistent roster snapshot.","Saved-roster recovery now has an executable regression check as well as its existing read-only safeguards.","No roster calculation, staffing, allocation, Pager, Reliever, five-nurse, realtime, privacy or write rule has changed."]],["37.5","18 Sep 2026","One dependable connection opens the roster",["The authorised account check, staffing, allocations and essential app settings now arrive as one protected database snapshot instead of several consecutive requests.","The opening screen no longer declares a connection problem while a normal slow database response is still in progress.","The saved-roster fallback remains read-only and available if the single shared request genuinely fails.","No roster calculation, allocation, Pager, Reliever, five-nurse, realtime, privacy or write rule has changed."]],["37.4","18 Sep 2026","The shared roster opens in dependable stages",["Startup now loads essential staffing first, then tonight’s allocation state, instead of making eleven database reads compete as one all-or-nothing request.","Settings, schema diagnostics and the realtime revision marker load quietly after the clinical roster is already visible.","Try again waits for an active request to finish before starting a genuinely fresh attempt, preventing overlapping startup requests.","The verified rotation, staffing, allocation, Pager, Reliever, five-nurse, realtime, privacy and database rules remain unchanged."]],["37.3","18 Sep 2026","Reliable roster opening and recovery",["The essential shared roster now has enough time to recover from a slow or cold database connection instead of being stopped just as it begins responding.","Recent activity history loads after the core roster opens, so a delayed history request can never block Night, Changes or Breaks.","Try again now shows clear progress, while the read-only saved-roster option safely repairs older or partial saved data before opening it.","The verified rotation, staffing, allocation, Pager, Reliever, realtime, privacy and database rules remain unchanged."]],["37.2","18 Sep 2026","A reliable way out of a stalled connection",["Startup checks now have clear time limits, so a delayed account or roster response cannot leave the opening screen indefinitely.","A calm Retry action lets the signed-in nurse try the shared connection again without losing the session.","When a saved snapshot is available, Use saved roster opens the last known roster as an explicitly read-only view until the shared connection returns.","Profile and administrator extras no longer block the core roster from opening, while the verified rotation, staffing, allocation, realtime and privacy rules remain unchanged.","The recovery state keeps the same Apple-style typography, spacing, contrast and reduced-motion behaviour as the rest of the launch experience."]],["37.1","15 Sep 2026","A calmer, safer way to update",["A quiet update notice now offers Details, Later and Update without opening a sheet or reloading while someone is working.","Update details show the incoming version, release date and exact changes before installation whenever fresh release information is available.","The update sheet confirms that shared roster data stays intact and keeps one clear Update now action with a reversible Later choice.","Future release information is checked network-first with a safe cached fallback, while activation still waits for explicit approval and reloads only once.","The notice and sheet use restrained Apple-style motion, high-contrast light and dark materials, 44-point touch targets and reduced-motion fallbacks.","The verified rotation and all staffing, allocation, Pager, Reliever, realtime, offline and privacy behaviour remain unchanged."]],["37.0","15 Sep 2026","Your night, made immediately useful",["Your night now leads with a clear personal assignment, role-specific icon and the exact position or Labour Ward part.","Working time, break and the relevant colleague or coverage context are separated into readable facts instead of being compressed into one line.","A Changed tonight marker appears only when the selected nurse’s own calculated assignment or Labour Ward order has changed for that night.","One contextual action opens the matching team allocation, absence review or private name choice without adding another bottom tab or repeating the full roster.","The card remains a solid high-contrast clinical surface in light and dark mode, with large touch targets and restrained motion.","The verified rotation and all staffing, Pager, Reliever, five-nurse, allocation, realtime, offline and privacy behaviour remain unchanged."]],["36.9","15 Sep 2026","A consistent appearance and focused confirmation",["Confirm now presents only roles that changed, with previous and new assignments shown clearly and the recorded reason kept alongside the review.","The complete plan remains available in a quiet View full plan disclosure without competing with the changed items.","Light, Automatic and Dark appearance choices now use one validated root state before the first paint, update the browser chrome and reapply after the app resumes.","Forms, cards, dialogs and navigation now draw from one final semantic surface layer, preventing isolated light cards or mismatched dark materials.","The verified rotation and all staffing, Pager, Reliever, five-nurse, allocation, realtime, offline and privacy behaviour remain unchanged."]],["36.8","15 Sep 2026","Less repetition and a leaner interface",["Confirm now stays quiet when nothing needs reviewing, instead of repeating the complete calculated roster.","Pager and Reliever appear once with their Labour Ward part and break shown beneath, removing duplicate first-part and second-part rows from confirmation and full-roster cards.","Unused legacy Labour Ward editor helpers and styling were removed after confirming they were no longer connected to the interface.","Every repository file was checked; production assets, forward-only migrations, tests, security guidance and deployment documentation remain because they are still required.","The verified rotation and all staffing, Pager, Reliever, five-nurse, allocation, realtime, offline and privacy behaviour remain unchanged."]],["36.7","14 Sep 2026","Calm native motion and clearer Apple-style controls",["Night, Changes and Breaks now use restrained directional navigation, compacting scroll headers, native press feedback and complete reduced-motion fallbacks.","Buttons, saved states, errors and operational status colours now follow one consistent semantic hierarchy with stronger light and dark mode contrast.","Recent activity is now an interactive grouped list, and each entry opens a private detail sheet showing its night, reason or allocation detail, actor and recorded time.","Typography scales more naturally across phone and desktop sizes, dense clinical cards remain solid, and translucency remains limited to navigation, headers, sheets and temporary feedback.","The verified rotation and all staffing, Pager, Reliever, five-nurse, allocation, realtime, offline and privacy behaviour remain unchanged."]],["36.6","14 Sep 2026","Clearer spacing and complete recent activity",["The selected date and staffing summary now have deliberate breathing room instead of appearing as one joined surface.","Night, Changes and Breaks sit in three clearly separated bottom-tab targets while retaining the restrained floating Apple-style navigation material.","Recent activity now includes the saved reason or allocation detail beneath each change, matching the useful context already available in the full Changes activity history.","Clinical cards remain solid and readable, while the verified roster and all staffing, allocation, realtime and privacy behaviour remain unchanged."]],["36.5","14 Sep 2026","Five-nurse night changes now save fully",["The database now accepts the reviewed custom five-nurse structure as well as the established six-role structure.","An agreed five-nurse arrangement can save an overtime nurse on full-night Labour Ward / Pager while the other four working nurses cover theatre.","The database still rejects missing roles, extra roles, blank names and duplicate nurses, while the atomic save continues to verify the exact team working that night.","Normal Reliever-first allocation, the verified permanent rotation, later nights and all existing staffing safeguards remain unchanged."]],["36.4","14 Sep 2026","Custom five-nurse roles that save reliably",["An agreed five-nurse night can now be rearranged using exactly the five nurses working, including overtime staff, with one combined full-night Labour Ward / Pager role and four theatre roles.","The normal Reliever-first five-nurse workflow remains the default; the custom editor is an explicit night-only alternative and never changes the permanent rotation.","Night-only role saves now use a schema-35 atomic operation that validates the effective team, prevents duplicate assignments, records actor and time history, and fixes the unsupported JSON object-length database call.","Older installed clients are routed through the corrected atomic validation, while realtime refresh, incomplete-plan protection and all established Pager and Reliever rules remain in place."]],["36.3","14 Sep 2026","Clearer dark mode and perfectly round header controls",["Header settings, account and appearance controls now keep a fixed circular shape on narrow phones, including profile photographs.","Dark-mode fields, selection controls and saved staffing records use solid dark surfaces with clearly readable labels, values and placeholders.","Night, Changes and Breaks tab labels and the Staffing, Allocation and Confirm control now retain strong contrast in both appearance modes.","Small operational headings and supporting text were raised while clinical cards remain solid and interface motion stays restrained.","The verified rotation, automatic Pager and Reliever order, staffing safeguards, realtime conflict protection and privacy controls remain unchanged."]],["36.2","14 Sep 2026","Meaningful colour and readable unavailable actions",["Recent activity again uses distinct, accessible colours for absence, overtime and allocation changes, while retaining text labels so meaning never depends on colour alone.","Unavailable actions remain clearly inactive without fading their wording or icons, and primary, secondary, destructive and date controls now share one consistent high-contrast treatment.","Night and Breaks explain the exact plan task that must be completed before briefing, break-copy and email actions become available.","The restrained Apple-style hierarchy, solid clinical surfaces, dark mode, verified rotation and all staffing and realtime protections remain unchanged."]],["36.1","14 Sep 2026","Restored personal choice and clearer visibility",["Roster highlighting is again selected privately on each device, while administrator Access returns to simple account activation controls.","The My upcoming nights and personal calendar section has been removed from Night.","Important labels, supporting text, selected controls and unavailable actions now use clearer contrast in both light and dark modes.","The verified rotation, atomic staffing writes, recent activity, briefing copy, realtime conflict protection and solid clinical surfaces remain unchanged."]],["36.0","13 Sep 2026","Personal planning with safer shared changes",["Verified account-to-roster identity binding now protects personal schedule features and is managed by roster administrators.","Your next published nights appear in a private signed-in view and can be exported as a personal calendar file without team names or roster details.","Night now includes recent activity, changed-since-last-opened feedback and a copyable briefing that stays unavailable while the plan is incomplete.","Absence and overtime changes require the established atomic database functions, preventing partial current-row and history writes.","Failed staffing and allocation actions offer a direct Retry while keeping the entered information on screen.","The final Night, Changes and Breaks structure now lives in the HTML, with larger important touch targets and more legible operational text.","The reviewed schema baseline and forward-only identity migration preserve existing migrations, rotation rules, privacy boundaries and realtime conflict protection."]],["35.6","12 Sep 2026","Clearer decisions and help throughout each night",["Staffing, Allocation and Confirm now show honest states without ticks for untouched automatic steps.","Night and Breaks summary items open the exact Absence, Overtime or allocation section they describe.","Absence, overtime and night-only role buttons become available only after the required information has been entered.","The role editor now reveals its reason and save actions only after a genuine night-only change, with a clear way to restore rostered roles.","Breaks removes duplicate ready-state information and keeps completed Labour Ward status informational.","Dedicated Apple-style information sheets explain what each screen does, what happens automatically and when confirmation is required.","Wording and overtime allocation status were refined without changing the verified roster or staffing rules."]],["35.5","11 Sep 2026","Clearer Apple spacing throughout the app",["Unrelated summary tiles, allocation cards, break groups and action sections now have clear space between them instead of visually merging.","Night, Changes, Breaks and administrator screens now share one consistent control gap and section rhythm across phone and desktop layouts.","Controls that genuinely work together—date navigation, workflow steps, appearance choices and action-sheet options—remain intentionally grouped.","The Apple-inspired glass treatment stays limited to navigation and supporting chrome, while clinical information, forms and warnings remain solid and easy to read.","Small-phone and dark-mode spacing, borders and surface separation were refined without changing roster, staffing or allocation logic."]],["35.4","11 Sep 2026","Liquid-glass navigation and unified app chrome",["The bottom navigation is now a floating liquid-glass tab bar with a clear selected destination and comfortable iPhone safe-area spacing.","Night, Changes and Breaks now share the same translucent header material, subtle inner highlights and restrained depth in light and dark mode.","Account controls, information buttons and segmented controls use one consistent native-style interaction language.","Short spring selection and press motion improves orientation while reduced-motion preferences continue to remove non-essential movement.","Clinical cards, forms, staffing warnings and allocation details remain solid and high-contrast for fast, reliable reading."]],["35.3","11 Sep 2026","Live updates that recover automatically",["Staffing, allocation and roster changes now appear on colleagues’ open devices without closing and reopening the app.","Realtime reconnects automatically after sleep, background use or a temporary connection interruption.","A quiet revision check catches missed events without replaying screen animations or interrupting the person using the app.","Night-only role changes and their audit history are now saved together as one database action.","Administrator exports now describe their scope accurately and include night-only role changes, while private profile details and photographs remain excluded.","Email recipients are loaded from protected app settings instead of being published in the website source."]],["35.2","7 Sep 2026","Clearer actions from Night through Breaks",["Night summary items now show interaction only when they lead to a useful action, and outstanding work uses an explicit review label.","Outstanding allocation shortcuts open and focus the first unresolved requirement, while blocked review actions explain exactly what remains.","Break copy and email actions remain legible but unavailable until the named staffing or allocation requirement is resolved.","Onboarding now follows the intended journey from purpose and app sections through roster identity, optional profile and optional passkey.","Opening and night-only role wording now state shared-roster, offline and one-night effects more directly."]],["35.1","7 Sep 2026","Consistent styling from one design-token system",["The existing Apple-inspired interface now draws its surfaces, text, teal accent, status colours, separators, spacing, corner radii, shadows, translucency and motion from one consolidated design-token layer.","Superseded duplicate CSS rules were removed without changing roster logic, staffing, authentication, shared data or realtime behaviour."]],["35.0","6 Sep 2026","Reliable allocation decisions and clearer app health",["Outstanding tasks now name the exact allocation that still needs a nurse, and a valid selection enables review immediately.","Night, Changes, Breaks, copied text and email continue to use the same effective staffing plan, with duplicate saved allocation records ignored safely.","Staffing Undo uses the versioned database functions, and a role-change audit failure is now reported instead of being hidden.","Administrator overview and diagnostics now show actionable roster, account, refresh, application, cache and database health information.","The update window shows only this release, while Version history keeps the complete newest-first archive in its own scrolling view.","Small-screen, dark-mode, focus, disabled-control and reduced-motion presentation received a focused accessibility refinement."]],["34.8","2 Sep 2026","Clearer allocations and professional roster names",["Selecting an overtime nurse now completes the visible allocation task immediately, so Review changes becomes available.","Pager and Reliever continue to set the Labour Ward order automatically without creating a hidden confirmation task.","Every Night allocation row now opens the night-only role editor, giving its chevron a clear purpose.","The provisional email and copy actions now keep high-contrast white labels and icons in light and dark mode.","The six permanent roster members now appear by their full professional names throughout Night, Changes, Breaks, the full roster and outgoing summaries.","Internal roster keys and historical records remain unchanged to protect the verified rotation and existing shared data."]],["34.7","2 Sep 2026","A calmer welcome from opening to onboarding",["The full Apple-inspired opening experience now appears on every fresh app launch while the roster is genuinely loading.","Slow connections receive a reassuring connecting message instead of leaving the opening screen unchanged.","Onboarding now shows a clear step count alongside the familiar progress dots.","The guide uses simpler descriptions for Night, Changes, Breaks, roster identity, passkeys and optional profile details.","Replayed onboarding closes with the correct Guide completed message rather than repeating the first-use welcome."]],["34.6","2 Sep 2026","The complete update archive, clearly visible",["The changelog now shows a clear Latest and Previous updates navigation row at the top.","Previous updates displays the number of preserved releases and jumps directly to the archive.","The release sheet uses one reliable scrolling area so every earlier changelog remains accessible on small phones.","Each release remains separated by version and is never merged into the current update."]],["34.5","2 Sep 2026","A warmer, faster opening experience",["Signed-in users now see a brief branded opening state only while the latest shared roster is loading.","The opening state changes to a personal welcome as soon as the roster is ready, then moves directly into Your night.","Signed-out users reach the sign-in screen without an unnecessary delay.","Account now includes View onboarding again, which safely replays the complete guide without resetting first-use completion.","Opening motion, translucency and loading feedback follow the same restrained Apple-inspired system as the rest of the app."]],["34.4","30 Aug 2026","A complete, scrollable update story",["The update window now includes the complete version history in one scrollable view.","The newest release is clearly labelled Current update, while all earlier work appears under Previous updates.","Past improvements remain separated by version so older features are never presented as newly added."]],["34.3","30 Aug 2026","Clearer record actions and accurate update history",["The update window now describes only the changes introduced in this version.","Version history once again keeps each earlier release as its own separate entry.","Absence records now use one discreet More button instead of placing Edit and Remove beside each other.","Edit and Remove are presented in a native-style action sheet, with the destructive choice clearly separated and coloured red.","Overtime records use the same consistent action pattern on narrow and wide screens."]],["34.2","30 Aug 2026","Reliable delivery of the final interface",["A fresh application cache ensures every interface file updates together.","The obsolete five-person model banner is removed, leaving one concise five-nurse arrangement card.","The completed profile and workflow refinements now load consistently in both the installed app and the website."]],["34.1","29 Aug 2026","Personal dashboard and quieter automatic workflow",["Saved profile photographs, preferred names and role titles now appear in Your night.","Optional profile setup is included in onboarding and can be replayed later from Account.","Save profile appears only after a profile detail or photograph has changed.","Standard six-nurse nights require no Pager decision or confirmation when the automatic roster order is unchanged.","Confirm displays Not needed without a misleading completion tick.","Five-nurse wording, break guidance and similar-name matching were corrected across the interface."]],["34.0","29 Aug 2026","Personal account and safer sign-in",["The account sheet adds editable personal details, a private profile photograph, appearance choices, installation help and onboarding replay.","Approved roster identities remain unchanged in shared allocation records and staffing history.","Supported devices can add an optional passkey using their normal fingerprint, face recognition or device PIN.","The introduction explains passkey privacy without suggesting that Night Roster receives biometric information.","Recent absence, overtime and agreed night-only role changes offer a temporary Undo action."]],["33.0","28 Aug 2026","Apple-style interface and guided first use",["The complete interface follows one consistent Apple-inspired system for typography, spacing, controls, materials and motion.","Sign in and account creation use a clearer, calmer welcome experience.","New shift members receive a guided introduction to Night, Changes and Breaks before choosing their roster name.","Wording across the main workflow was simplified so automatic states remain quiet and actions say exactly what they do."]],["32.2","28 Aug 2026","Cleaner automatic allocation view",["An ordinary six-nurse night opens without the redundant calculated-plan status banner.","The duplicate Labour Ward order card was removed while Pager and Reliever remained visible in the allocated-roles list.","Detailed allocation controls remain available whenever staffing changes or an agreed night-only role swap requires them."]],["32.1","28 Aug 2026","Automatic standard plan and native motion",["A standard six-nurse plan no longer asks for unnecessary confirmation when Pager and Reliever follow their automatic roster order.","Confirmation remains required after absences, overtime allocations, five or seven-nurse decisions, or agreed night-only role changes.","The bottom navigation, screen headers and overlays now use controlled translucent materials with solid clinical content surfaces.","Short spring-style transitions clarify taps, tab changes, sheets and screen navigation without delaying roster information.","Reduced-motion settings continue to remove non-essential movement automatically."]],["32.0","28 Aug 2026","Apple-inspired roster redesign",["Night, Changes and Breaks now share one calm mobile design system with grouped surfaces, hairline separators and consistent typography.","Your own allocation remains the first priority on Night, followed by a clearly interactive four-part staffing summary and a compact team list.","Changes now presents the selected night, workflow stages and staffing forms in one coherent working surface without competing coloured panels.","Breaks now prioritises the actual break groups while keeping staffing and Labour Ward status immediately accessible.","The bottom tab bar, controls, dialogs and dark mode were refined together, while all roster calculations, automatic Labour Ward rules and night-only role swaps remain unchanged."]],["31.3","28 Aug 2026","Calmer Changes workspace",["Staffing Changes now uses a compact light header with a restrained teal accent instead of an oversized coloured block.","The selected night and live staffing count sit together in one neatly aligned row, keeping more of the working form visible.","Staffing, Allocation and Confirm now form one slim segmented control with the numbers 1, 2 and 3 always visible and completed stages marked separately.","Borders, spacing and shadows were refined throughout the Changes screen for a quieter, more consistent mobile interface.","Dark mode now applies one coherent dark surface across the complete Changes screen instead of mixing dark and white sections."]],["31.2","28 Aug 2026","Secure password recovery",["The sign-in screen now includes a clear Forgot password option.","Authorised nurses can request a secure recovery email without administrator intervention.","Opening the email link returns to a dedicated new-password form inside the roster app.","The new password must be entered twice and contain at least eight characters before it is saved.","Existing roster access permissions, roles, staffing data and history remain unchanged."]],["31.1","28 Aug 2026","Simplified Labour Ward workflow",["Pager now takes Labour Ward first part and second break automatically, with no separate first-part selector to complete.","Reliever now takes Labour Ward second part and first break automatically.","The single Change tonight’s roles editor remains available for agreed night-only swaps across any core allocation.","Allocation instructions no longer ask staff to divide Labour Ward manually.","The complete motto now wraps cleanly on narrow phone screens instead of being cropped."]],["31.0","27 Aug 2026","Automatic night roles and clearer summary",["On a standard six-nurse night, the rostered Pager now automatically works Labour Ward first part and takes second break.","The rostered Reliever automatically works Labour Ward second part and takes first break, while an agreed swap can still be saved for that night only.","A new night-only role editor can swap any two core allocations without changing the permanent rotation or later nights.","Night summary now shows nurses, absences, overtime and outstanding tasks in a clearly tappable two-by-two layout.","First Part, Second Part, Pager and Reliever now use role-specific symbols that directly match their meaning."]],["30.1","27 Aug 2026","Complete release history",["The update window now keeps a scrollable history of recent releases instead of replacing the previous notes.","Release notes use smaller, more readable mobile typography with the newest version shown first.","Every future entry can describe its actual changes while all earlier entries remain available below it."]],["30.0","27 Aug 2026","Unified mobile interface",["Night, Changes and Breaks now share one consistent light design system, with a coherent dark mode when deliberately enabled.","A new matching line-icon family is used for the bottom tabs, staffing summaries and allocation roles.","All summary cards are clearly interactive and open the relevant staffing, allocation or confirmation step.","Workflow steps always retain the numbers 1, 2 and 3, with a separate tick showing completed stages.","The Changes date and staffing controls remain compact and side by side on mobile screens."]],["29.0","27 Aug 2026","Re-composed shift screens",["Night, Changes and Breaks were separated into clearer task-focused screen compositions.","The Night screen prioritised the signed-in nurse’s own allocation before the full team situation.","Changes introduced a dedicated three-stage working surface for staffing, allocation and confirmation.","Breaks introduced distinct First break, Second break and Labour Ward sections."]],["28.0","27 Aug 2026","Personalised Night screen",["The old “I am” control was replaced with a personalised Your night section.","The nurse’s role, working period and break became immediately visible without reading the full roster.","A contextual Labour Ward message appears when that nurse’s own allocation is not final.","Live nurse numbers, absences and outstanding tasks were moved into a compact summary."]],["27.0","26 Aug 2026","Workflow and readability update",["Dates became easier to read and open through a mobile-friendly calendar control.","Changes was organised into Staffing, Allocation and Confirm stages.","Allocation cards became smaller and colours were standardised by role.","Optional overtime-name suggestions were added while keeping free-text entry available.","Subtle loading and saved-state feedback were introduced."]],["26.2","26 Aug 2026","Cleaner roster shortcuts",["The current or next-night shortcut is hidden when the correct roster night is already open.","View full roster expands to the available width when no return shortcut is needed."]],["26.1","26 Aug 2026","Clearer automatic-night navigation",["Night shortcut buttons were made equal in size.","Labels now explain whether the app will return to the current working night or the next roster night.","The shortcut becomes inactive when its target night is already selected."]],["26.0","26 Aug 2026","Reliability and publishing foundation",["Automated safety checks were added for the verified roster rotation, staffing calculations and 07:00 working-night boundary.","The app gained clearer version, database-schema and connection diagnostics.","Night-plan confirmation and Labour Ward ordering were strengthened while earlier published roster nights remained protected.","The progressive web app update process was improved so new versions can be installed safely."]]].map(function(e){return{version:e[0],date:e[1],title:e[2],changes:e[3],policy:e[4]}});
